programs.sol:
"""A surface-form approximation: verb endings, split characters and title labels.

The strongest readable signals are Korean and Japanese past-tense endings.
A few large responses are tokenization effects: a continuation byte following
an isolated UTF-8 lead byte, or a colon immediately after an opening 'Title'.
The unfinished byte prefixes of 했 and 떴 get an extra negative impulse.
Punjabi spellings of India and the start of 'republic' get positive values.
Most other tokens stay near zero. Fine lexical and byte-fragment variation
is deliberately left unmodeled.
"""

import unicodedata

READS = ()
DOUBLE_S_CODA = '\N{HANGUL JONGSEONG SSANGSIOS}'


def double_s_coda(character):
    return unicodedata.normalize('NFD', character).endswith(DOUBLE_S_CODA)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, previous, tail = 0, b'', b''
    else:
        _, pos, previous, tail = carry
    tail = (tail + b)[-32:]
    text = tail.decode('utf-8', 'replace')
    value = 0.0

    # Closed grammatical classes, rather than a vocabulary-wide token table.
    word = s.strip()
    if word in ('었', '았', '했'):
        value = -5.5
    elif word == '여':
        value = -6.8 if previous.endswith('보'.encode()) else -1.1
    elif word == '하였':
        value = -4.3
    elif word == '였':
        value = -2.4
    elif word and double_s_coda(word[-1]) and word[-1] not in '있겠':
        # Exclude the existence and future markers from the past-coda rule.
        value = -2.3
    if word == 'かった' or (word == 'った' and previous.endswith('か'.encode())):
        value = -2.85
    elif word.endswith('だった'):
        value = -1.3
    elif word.endswith(('ていた', 'があった')):
        value = -1.1
    elif word == 'った':
        value = -0.75
    elif word.endswith('ている'):
        value = -0.4
    elif word in ('た', 'した', 'ました'):
        value = -0.18
    elif word.endswith('てしまう'):
        value = -0.7
    elif word in ('良かった', 'なかった'):
        value = -0.4
    elif word == 'する':
        value = 0.35
    elif word == 'ен':
        value = -0.33

    # Single-byte tokens can finish a character begun by the previous token.
    if len(b) == 1 and 0x80 <= b[0] < 0xc0:
        # The first continuation of an isolated three-byte character prefix.
        if previous and 0xe4 <= previous[-1] <= 0xe9:
            value = -1.4 if previous[-1] == 0xe9 else -0.1
        elif previous and 0xea <= previous[-1] <= 0xed:
            value = -1.3
        # The ambiguous, unfinished spellings of 했 and 떴 are especially strong.
        partial = previous[-1:] + b
        if any(verb.encode().startswith(partial) for verb in ('했', '떴')):
            value = -10.0
        if text.endswith('つ'):
            value = -3.7
        elif text.endswith('だ'):
            value = -3.3
        elif text and double_s_coda(text[-1]):
            value = -9.0
        elif text.endswith('ਭਾਰਤ'):
            value = 4.0
        elif text.endswith('ਗਣਤ'):
            value = 2.7

    if pos == 1 and previous == b'Title' and b == b':':
        value = -8.08
    elif pos == 0 and not value:
        # The first token has a separate, generally negative baseline.
        if word and word[-1].isalpha():
            value = -0.16
        elif s.isspace():
            value = -0.3
    return (doc, pos + 1, b, tail), float(value)

"""A partial syntax-based approximation of this component.

Spaced assignments to bare variables get strong negative values; fields,
loop variables and default arguments get weaker responses. A standalone
space after a newline is positive, especially after a literal backslash-n.
Completing selected escaped UTF-8 lead bytes is also positive. At text
boundaries, a coarse casing/spacing prior estimates the larger initial
activations. Other noninitial tokens default to zero: word-specific residual
variation is deliberately not stored in a token lookup table.
"""
import re

READS = ()

CODE = re.compile(
    r'\b(?:def|import|public|private|const|var)\s|\bfunction\s*\w*\s*\(|'
    r'\blet\s+(?:mut\s+)?\w+\s*[:=]|\b(?:self|this)\.|'
    r'\b(?:for|if|while|print|printf)\s*\(|;\s*\n|\{\s*\n|(?<![=-])=>|'
    r'\w+\.\w+\('
)
NAME = re.compile(r'([A-Za-z_$][A-Za-z_0-9$]*)$')
MODIFIERS = re.compile(
    r'^(?:(?:export|static|final|private|public|protected|const|let|var|mut)\s+)'
)
BUILTIN = re.compile(
    r'^(?:auto|bool|char|double|float|int|long|short|signed|unsigned|'
    r'string|size_t|std::)\b'
)


def assignment(text):
    normalized = text.replace('\\n', '\n').replace('\\t', '\t')
    line = normalized.rsplit('\n', 1)[-1].strip()
    line = line.replace('`', '')
    line = re.split(r'[;{}]', line)[-1].strip()
    line = re.sub(r'^\d+\s*[|:]?\s*', '', line)
    match = NAME.search(line)
    if not match:
        return 0.02
    name = match.group(1)
    left = line[:match.start()].rstrip()
    code = bool(CODE.search(normalized))
    if left.endswith('.'):
        if re.search(r'\bself\.', line):
            return -0.32
        return -0.18 if re.search(r'\bthis\.', line) else 0.08
    if ':' in left and ('(' in line or left.count(':') == 1):
        return -0.10
    if '(' in line and not line.startswith('for'):
        return -0.05
    if line.startswith('for'):
        return -0.18
    if left and not re.search(r'[+\-=*/]', left):
        typed = code and re.match(r'^[A-Z][\w:<>,]*\s', line)
        if MODIFIERS.match(line) or BUILTIN.match(line) or typed:
            return -0.62
    if not left or left == '$':
        identifier = '_' in name or bool(re.search(r'[a-z][A-Z]', name))
        indented = normalized.rsplit('\n', 1)[-1].startswith(('  ', '\t'))
        if code or indented or (identifier and len(name) > 4):
            return -0.70
        if name.startswith('$'):
            return -0.62
        if len(name) > 2 and name.isupper():
            return -0.30
        return 0.01
    return 0.02


def start_value(token):
    """A coarse negative prior at a fresh text boundary, by token shape."""
    if token.startswith('<|') or token.strip().isdigit():
        return 0.0
    if token.isspace():
        return -0.30 if '\n' in token else -0.68
    word = token.strip()
    if word.isascii() and word.isalpha():
        if token[0].isspace():
            return -0.10
        if word.isupper():
            return -0.25
        return -0.60 if word.istitle() else -0.35
    return -0.20


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc or carry[2]
    text = '' if fresh else carry[1]
    token = prefix.token_strings[-1]
    value = start_value(token) if fresh else 0.0
    if token in (' =', ' :=', ' <-'):
        value = assignment(text)
        if token == ' :=':
            value = min(value, -0.55)
        elif token == ' <-':
            value = min(value, -0.50)
    elif token == ' ' and not fresh:
        if text.endswith('\\n'):
            value = 0.70
        elif text.endswith('\n'):
            value = 0.19
    # These byte leads begin commonly escaped UTF-8 symbols and ligatures.
    tail = (text[-8:] + token).lower()
    if tail.endswith('\\xc2'):
        value = 0.65
    elif tail.endswith(('\\xe2', '\\xef')):
        value = 1.15
    boundary = token == '<|endoftext|>'
    return (doc, (text + token)[-600:], boundary), value

programs.haiku:
"""layers.1.mlp.down_proj:1410 -- the preposition that completes a participle or adjective.

This component fires on the preposition right after a word that says what something is
full of, covered in, made of, or controlled/surrounded by: "full OF", "filled WITH",
"rich IN", "covered IN", "made OF", "composed OF", "surrounded BY", "occupied BY",
"made FROM", "hungry FOR". The activation is large and positive there (about 3 to 7).
It is near zero on most other tokens, and it is negative (about -5) on the Greek-style word
fragments "oph" / "ophil" (e.g. Melanophyllaceae, pedophile), which are the rare
exception.

The program is a lookup on the previous word and the current token, built from word
groups a reader can check: fill/cover words, make/compose words, control/agent passives,
and desire words. Stronger matches get larger values. Any other past participle followed
by by/with/of/from gets a small value. Everything else is 0.
"""

READS = ()

# Words that say a thing is full of, filled with, covered in, or otherwise furnished with something.
# The most typical fill and cover words.
STRONG = {"full", "filled", "covered", "rich", "packed", "loaded", "laden"}
FILL = {"full", "filled", "packed", "stuffed", "loaded", "laden", "crowded", "flooded", "topped",
        "adorned", "decorated", "lined", "covered", "coated", "wrapped", "dressed", "immersed",
        "stained", "armed", "equipped", "supplied", "rich", "complete", "dripping", "overwhelmed"}
IN_WORDS = {"rich", "covered", "wrapped", "clad", "dressed", "immersed", "high", "low", "steeped"}
MADE_OF = {"full", "made", "composed", "comprised", "free", "devoid", "bereft"}
SOURCE_OF = {"consisting", "consist", "consists", "consisted", "source", "sources", "network",
             "capable", "collection", "mixture", "mix", "team", "abundance", "plethora"}
MADE_FROM = {"made", "formed", "constructed", "crafted", "assembled", "built"}
# Passive verbs where "by" introduces what surrounds, occupies or controls the subject.
CONTROL = {"surrounded", "occupied", "led", "dominated", "ruled", "governed", "guided", "founded",
           "powered", "haunted", "driven", "followed", "accompanied", "influenced", "characterized",
           "owned", "backed", "controlled", "inspired", "sponsored", "supported"}
# Mid-word fragments, with their typical activation.
FRAGMENTS = {"oph": -4.8, "ophil": -4.0, "roph": -1.4, "フォ": -3.0, "of": -1.8}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur_raw = toks[-1]
    # A word fragment with no leading space sits inside a longer word.
    if not cur_raw.startswith(" ") and cur_raw.strip() in FRAGMENTS:
        return None, FRAGMENTS[cur_raw.strip()]
    if len(toks) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    cur = cur_raw.strip().lower()
    prev = toks[-2].strip().lower()
    if cur == "with" and prev in FILL:
        v = 3.7 if prev in STRONG else 2.2
    elif cur == "in" and prev in IN_WORDS:
        v = 3.7
    elif cur == "of" and prev in MADE_OF:
        v = 3.7
    elif cur == "of" and prev in SOURCE_OF:
        v = 2.2
    elif cur == "from" and prev in MADE_FROM:
        v = 3.0
    elif cur == "by" and prev in CONTROL:
        v = 3.7
    elif cur == "for" and prev in {"hungry", "thirsty", "appetite", "penchant", "need", "room",
                                   "craving", "desire", "hunger"}:
        v = 3.0
    elif cur in ("with", "by", "of", "from") and prev.endswith("ed"):
        v = 0.75
    else:
        v = 0.0
    return None, v

programs.sol:
"""A detector for choosing members of a set: 'one/which/some of ...'.

The strongest response is on 'of' after an indefinite selector or count,
not ordinary possessive 'of'. Broad 'all/most/much of' is much weaker.
There are also translated 'one of' patterns, membership expressed with
'be among', 'choose from', and a small echo on a following 'the'.
The recent byte suffix is retained so split Unicode words reassemble.
"""
import re
import inflect

READS = ()

SELECTORS = {
    'one': 1.5, 'which': 2.0, 'any': 1.55, 'each': 1.4,
    'either': 1.55, 'neither': 1.1, 'none': 1.17,
    'some': .88, 'many': 1.05, 'several': 1.15,
    'few': .82, 'both': .6, 'another': .9,
    'all': .15, 'most': .12, 'much': .13,
}
_inflector = inflect.engine()
NUMBER_WORDS = {_inflector.number_to_words(n) for n in range(2, 101)}
# Translated 'one of', keeping each language's prepositions together.
ONE_BEFORE_PREPOSITION = {
    'de': set('un une uno una um uma'.split()),
    'des': {'un', 'une'},
    'dos': {'um', 'uma'},
    'das': {'um', 'uma'},
    'di': {'uno', 'una'},
    'dei': {'uno', 'una'},
}
ROMANCE_SOME = set('alguno alguna algunos algunas alguns algumas '
                   'plusieurs chacun chacune uns unes'.split())
RUSSIAN_ONE = set('один одна одно одни одну одного одной одному одним '
                  'одними одних одном'.split())
COPULAS = set('is are was were be been being'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail, echo = carry if carry is not None else (None, b'', 0.)
    if old_doc != doc:
        tail, echo = b'', 0.
    before = tail.decode('utf-8', errors='ignore').lower().rstrip()
    match = re.search(r'(\w+)$', before)
    previous = match.group(1) if match else ''
    word = prefix.token_strings[-1].strip().lower()
    value, next_echo = 0., 0.

    if word.lstrip('-_') == 'of':
        if previous in SELECTORS:
            value = SELECTORS[previous]
        elif previous in NUMBER_WORDS:
            value = 1.15
        elif previous.isdecimal():
            value = .28
        elif previous == 'more':
            value = 1.25 if before.endswith('or more') else .2
        elif previous == 'out':
            value = .08
        if value > .5:
            next_echo = .44 if previous == 'one' else .1
            if previous in NUMBER_WORDS:
                next_echo = .35
            elif previous == 'each':
                next_echo = .29
            elif previous == 'any':
                next_echo = .23
            elif previous == 'none':
                next_echo = .18
            elif previous == 'some':
                next_echo = .02
    elif word == 'the' and echo:
        value = echo
    elif word == 'among':
        value = .97 if previous in COPULAS else .1
    elif word == 'from' and previous in {'choose', 'chooses', 'choosing', 'chose'}:
        value = .5
    elif word in ONE_BEFORE_PREPOSITION:
        if previous in ONE_BEFORE_PREPOSITION[word]:
            value = 1.55
            if previous == 'un' or (previous == 'une' and word == 'de'):
                value = .95
            if re.search(r"l['’]une?$", before):
                value = 1.9 if previous == 'une' else 1.6
        elif previous in ROMANCE_SOME and word == 'de':
            value = 1.05
        elif previous in {'alguns', 'algumas'} and word in {'dos', 'das'}:
            value = 1.05
    elif word == 'из':
        if previous in RUSSIAN_ONE:
            value = 1.55
        elif previous in {'некоторые', 'некоторых', 'каждого', 'каждый',
                          'каждой', 'любой', 'любого', 'любых'}:
            value = 1.05
    elif word in {'der', 'von'} and previous in {'eine', 'einer', 'eines', 'einem'}:
        value = 1.35
    elif word == 'van' and previous in {'een', 'één'}:
        value = 1.6
    elif word == 'z' and previous in {'jeden', 'jedna', 'jednym'}:
        value = 1.8
    elif word == 'trong' and previous == 'một':
        value = 2.1

    tail = (tail + prefix.token_bytes[-1])[-128:]
    return (doc, tail, next_echo), value

"""Approximate a negative spelling pulse, strongest on short 'ger' pieces.

Recognize g + one vowel + r within a token or across word-piece boundaries,
after case folding and script transliteration. The vowel and current piece's
length set the pulse size. English token frequency calibrates very short and
longer pieces. Weaker signed corrections cover a nearby g/r across a boundary
and vowels immediately following g. State holds the current word's last
letters and resets at document boundaries. This is a partial orthographic
approximation; it omits token-specific strengths and much contextual variation.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def folded(text):
    return anyascii(text).lower()


@lru_cache(maxsize=8192)
def frequency(text):
    return zipf_frequency(text.strip().lower(), 'en')


def syllable_value(vowel, length, freq, follows_g):
    if length <= 3:
        if vowel in 'ea':
            if length <= 2:
                return -0.70 if freq <= 1.75 else -2.75
            return -5.12 if vowel == 'e' else -2.80
        if vowel == 'i':
            return -1.65
        return -0.39 if follows_g else -0.15
    if length <= 5:
        if vowel == 'e':
            return -2.54 if length == 4 else -1.17
        return -0.54 if vowel == 'a' else -0.07
    if length == 6:
        return -0.67 if freq <= 4.25 else -0.04
    return -0.05 if freq <= 4.25 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    token = folded(text)
    joined = tail + token
    cut = len(tail)
    length = len(token.strip())
    follows_g = tail.endswith('g') and token[:1] in 'aeiouy' and bool(token)
    matches = [m for m in re.finditer(r'g[aeiouy]r', joined)
               if m.end() > cut]
    value = -0.003
    if matches:
        vowel = matches[-1].group()[1]
        need_freq = length <= 2 or length >= 6
        freq = frequency(text) if need_freq else 0.0
        value = syllable_value(vowel, length, freq, follows_g)
    else:
        nearby = [(g, r) for r, ch in enumerate(joined) if ch == 'r' and r >= cut
                  for g in range(max(0, r - 6), min(r, cut))
                  if joined[g] == 'g' and joined[g:r].isalpha()]
        if nearby:
            g, r = min(nearby, key=lambda pair: pair[1] - pair[0])
            if length <= 3:
                value = -1.44 if follows_g else -0.34
                if not follows_g and len(joined) - r > 2:
                    value = 0.0
            elif length == 4:
                value = -0.45 if follows_g else -0.08
            else:
                value = -0.05 if r - g <= 5 else 0.15
        elif follows_g and frequency(text) <= 3.25:
            value = -0.11 if 'g' in token else -0.05
    last_word = re.search(r'[a-z]+$', joined)
    tail = last_word.group()[-12:] if last_word else ''
    return (doc, tail), value

programs.haiku:
"""Layer-1 MLP neuron 1414 (the down_proj component 1414) as a readable spelling rule.

This component is almost exactly one hidden neuron of layer 1's MLP, and it goes strongly
negative in one situation: when the letters "ger" or "gar" are being spelled out inside a
word or name that the tokenizer has split into pieces. Examples: "Ger|hard", "Sulz|berger",
"Ang|ers" (Angers), "merg|ers" (mergers), "Rug|er", "Rog|ers", "Hof|ger|icht", "Schwarzeneg|ger".
Whole words that happen to contain the letters in one token ("German", "Germany", "garden",
"danger", "integer", "manager") stay near zero.

The program walks the text token by token and keeps the letters of the current word so far.
It predicts:
  * a strong negative value when the piece itself is the bare sound "ger" (or "gar");
  * a medium negative value when the piece is a longer ending that contains it ("berger",
    "anger", "gers", ...);
  * a weaker negative value when this piece is the one that completes "ger"/"gar" across
    a word's pieces (the word so far did not yet contain it);
  * zero everywhere else.
"""

READS = ()

GER_GAR_PIECES = {"ger": -5.0, "gar": -3.0, "гер": -4.0, "гар": -3.0}
GER_ENDING_PIECES = {
    "berger", "iger", "ager", "eger", "gers", "agers", "gere", "germ",
    "anger", "inger", "enger", "agger",
}


def has_ger_or_gar(word):
    return "ger" in word or "gar" in word


def step(carry, prefix, upstream):
    """carry: the letters of the current word so far (lower case), None at a row start."""
    piece = prefix.token_strings[-1]
    text = piece.strip().lower()
    new_document = len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    continues = (
        carry is not None
        and not new_document
        and text.isalpha()
        and not piece.startswith(" ")
    )
    before = carry if continues else ""
    word = before + text if (continues or text.isalpha()) else ""

    if text in GER_GAR_PIECES:
        value = GER_GAR_PIECES[text]
    elif text in GER_ENDING_PIECES:
        value = -3.0
    elif continues and has_ger_or_gar(word) and not has_ger_or_gar(before):
        value = -1.5
    else:
        value = 0.0
    return word, float(value)

programs.sol:
"""Approximate the dominant numeric-punctuation peaks, plus lexical exceptions.

Unspaced hyphens, slashes and en dashes after ASCII digits respond positively.
En dashes and year-like numbers (1500--2100) get larger values. Hyphen/slash
responses weaken around arithmetic markers, letter prefixes and numeric chains.
URL scheme punctuation gets a fixed response; capitals give a small fallback.

Negative rules cover "again" (especially "once again"), "once more", and the
colon of a document-initial "Title:" heading. Other lexical/character effects
are left at zero. A 100-character tail resets at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ":" and text == "Title":
        value = -11.5
    elif token == " again":
        value = -4.4 if re.search(r"\bonce\Z", text, re.I) else -0.35
    elif token == " more" and re.search(r"\bonce\Z", text, re.I):
        value = -2.0
    elif token == "://":
        value = 1.6
    elif token in ("-", "/", "–"):
        number = re.search(r"[0-9]+\Z", text)
        if number:
            digits = number[0]
            before = text[:number.start()]
            year = len(digits) == 4 and 1500 <= int(digits) <= 2100
            if token == "–":
                value = 3.6 + 1.7 * year
            else:
                slash = token == "/"
                value = 3.0 if slash else 1.7
                value += (2.2 if slash else 1.7) * year
                if slash and len(digits) == 2:
                    value += 1.2
                if len(digits) > 4:
                    value -= 0.6
                if before[-1:].isalpha():
                    value -= 1.3 if slash else 0.7
                if before[-1:] and before[-1:] in "-/–.,":
                    value -= 1.0 if slash else 0.5
                if re.search(r"[0-9][-/–]\Z", before):
                    value -= 0.3 if slash else 0.5
                if re.search(r"[=^+*√]|\\(?:frac|sqrt)", before[-32:]):
                    value -= 1.5 if slash else 1.0
                if re.search(r"[0-9]" + re.escape(token) + r"[0-9]", text[-50:]):
                    value -= 0.5 if slash else 0.2
                value = max(0.0, value)
        elif text[-1:].isupper():
            value = 0.7 if token == "-" else 0.3
    return (doc, (text + token)[-100:]), value

"""Sparse approximation of document-format and programming-text responses.

Negative pulses mark initial carriage-return runs, opening // comments,
and the colon in an opening 'Title:'. Initial 'test' and 'void' are positive.
Middle-dot separators are negative. Smaller rules cover familiar code,
metadata, indentation, prepositions, and comparison words. State resets at
new documents. All other content gets 0.002: most lexical variation is
not captured by these rules.
"""
import re

READS = ()

# Common source-code, configuration, markup, and plain-text file suffixes.
TEXT_FILE_SUFFIXES = frozenset(
    '.py .js .ts .rs .sh .json .java .c .h .cpp .go .css .html '
    '.xml .yaml .yml .md .txt .sql'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, first, repeated = 0, '', s, True
    else:
        _, old_position, previous, first, repeated = carry
