    "underlying", "corresponding", "accompanying", "nearby", "surrounding", "resulting",
    "outermost", "topmost", "leftmost", "rightmost", "innermost", "uppermost",
    "easternmost", "westernmost", "northernmost", "southernmost",
}
MEDIUM = {
    "existing", "associated", "subsequent", "respective", "necessary", "preceding",
    "trailing", "downstream", "upstream", "ongoing", "prevailing", "neighboring",
    "resultant", "outgoing", "consequent", "affiliated", "surviving", "pending",
    "remaining", "contributing", "ancillary", "embedded", "flanking", "confounding",
}
WEAK = {
    "adjacent", "leading", "related", "incoming", "upcoming", "outstanding", "appended",
    "overlapping", "closest", "nearest", "applicable", "overall", "additional",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
