"""Horse words, Mac spellings and middle-dot leaders (sparse, mostly lexical).

Layer-1 MLP feature that is almost silent on ordinary text. Its large values come
from a few specific tokens, and the program predicts those, and 0 elsewhere:
- the horse word 馬/马 (also 马上 "at once"), the Korean 말 and the Arabic ما
  ("what"): strongly negative (about -5);
- Arabic words ending in ما (فيما, لما, وما, بما, مما): mildly negative (-2);
- the Latin spellings Mac, mac, MAC, Mast, mast, Ma, MA: mildly negative (-0.8);
- English "horse", "horses", "mare", "mares": weakly negative (-0.5);
- a run of middle dots (·· leader tokens): a constant positive value (+1).
Everything else is predicted as 0. Context is ignored: each token is judged alone.
"""
READS = ()

HORSE = {"馬", "马", "马上", "말", "ما"}
HORSE_VALUE = -5.0
ARABIC_MA_WORDS = -2.0
DOT_VALUE = 1.0
MAC_WORDS = {"Mac", "mac", "MAC", "Mast", "mast", "Ma", "MA"}
MAC_VALUE = -0.8
ENGLISH_HORSE = {"horse", "horses", "mare", "mares"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if "·" in token:
        return carry, DOT_VALUE
    if token in HORSE:
        return carry, HORSE_VALUE
    if token.endswith("ما") and token != "كما":
        return carry, ARABIC_MA_WORDS
    if token in MAC_WORDS:
        return carry, MAC_VALUE
    if token.lower() in ENGLISH_HORSE:
        return carry, -0.5
    return carry, 0.0

