"""A date-prefix pulse, rather than a general response to digits.

At the second digit of 19... or 20..., choose a strength from recognizable
contexts: citations, copyright, temporal words, months, or punctuation.
Code-like punctuation, quantity words and dense digits weaken it. Nearby
ASCII letters and Han text strengthen it.
The next digit has a small negative echo. There are also weak responses to
30/31 and a pulse for Chinese 一九. Other positions get zero.
"""
import calendar
import re
import regex

READS = ()
DIGITS = '0123456789'
MONTH = re.compile(r'\b(?:' + '|'.join(
    list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:]
) + r')\b', re.I)
TEMPORAL = re.compile(
    r'\b(?:in|since|during|from|until|between|before|after|by|circa|born|died|year|'
    r'the|spring|summer|autumn|fall|winter)\s*$', re.I,
)
CITATION = re.compile(r'\bet\s+al[.,]*(?:\s*\()?\s*$', re.I)
QUANTITY = re.compile(
    r'\b(?:than|equals?|radius|velocity|length|width|height|weight|approximately|about)'
    r'\s*(?:of\s*)?$', re.I,
)


def year_pulse(before, number):
    """An ordered set of date-context clues, plus numeric-text corrections."""
    last = before[-40:]
    if CITATION.search(last):
        value = 0.845
    elif re.search(r'©\s*$', last):
        value = 0.775
    elif TEMPORAL.search(last):
        value = 0.625
    elif MONTH.search(last):
        value = 0.515
    elif before.endswith('('):
        value = 0.50
    elif before.endswith('/'):
        value = 0.35
    elif before.endswith((' ', '\n')):
        value = 0.30
    else:
        value = 0.175
    value += 0.17 * (number == '19')
    value -= 0.17 * any(c in last[-24:] for c in '{}_`\\=<>')
    value -= 0.40 * bool(QUANTITY.search(last))
    value += 0.405 * bool(regex.search(r'\p{Script=Han}', last[-16:]))
    value += (0.15 * sum(c.isascii() and c.isalpha() for c in last)
              - 0.355 * sum(c.isdigit() for c in last)) / 40
    return max(0.0, min(1.3, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, text, number = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in DIGITS:
        number = (number + token)[-8:]
        if number in ('19', '20'):
            value = year_pulse(text[:-1], number)
        elif len(number) == 3 and number[:2] in ('19', '20'):
            if number.startswith('19'):
                value = -0.02 - 0.008 * int(token)
            else:
                value = -0.10 if token in '12' else -0.04
        elif number.endswith('30'):
            value = 0.19
        elif number.endswith('31'):
            value = 0.105
    else:
        number = ''
        if token == '九' and text.endswith('一'):
            value = 1.15
    text = (text + token)[-120:]
    return (doc, text, number), value

