    bases = set(wordnet.base_forms(word, 'noun'))
    if word == 'people':
        return 'people'
    if bases & {'person', 'individual', 'human'}:
        return 'human'
    if bases & {'man', 'woman', 'boy', 'girl', 'child', 'kid',
                'male', 'female', 'adult'}:
        return 'age_gender'
    if 'patient' in bases:
        return 'patient'
    if 'student' in bases:
        return 'student'
    categories = wordnet.categories(word, 'noun')
    if 'noun.person' in categories:
        # An everyday verb with a rare person sense (e.g. 'have') is
        # not as good evidence of a human antecedent as 'student'.
        if (categories <= {'noun.person', 'noun.group'}
                and 'verb' not in wordnet.parts_of_speech(word)):
            return 'person'
        return 'ambiguous'
    if 'noun.group' in categories:
        return 'group'
    return 'other'


def advance(word, token):
    if not token:
        return ''
    if token[0].isspace():
        stripped = token.strip()
        return stripped.lower() if stripped.isalpha() else ''
    if token.isalpha():
        return (word + token.lower())[-64:]
    return ''


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    current = token.strip().lower()
    index = RELATION_INDEX.get(current)
    if index is not None:
        value = RESPONSES[antecedent(word)][index]
    elif current == 'where':
        value = -.02
    elif current == 'whom':
        value = .45
    elif current == 'whose':
        value = .3 if antecedent(word) == 'person' else 0.
    elif current == 'else' and antecedent(word) == 'indefinite':
        value = -.65
    else:
        value = 0.
    # Nonrestrictive relative clauses commonly start after punctuation.
    if prefix.position > 0 and prefix.document_ids[-2] == document:
        separator = prefix.token_strings[-2].strip()
        if current in {'which', 'where'} and separator in {',', '('}:
            value = -.33 if separator == ',' else -.63
        elif current == 'who' and separator == ',':
            value = .26
    return (document, advance(word, token)), float(value)

