"""Local numeral continuation, especially a nonzero digit following 2.

The after-2 continuation is weaker inside a longer number or across a separator.
There are smaller responses after 6 and 8. Document beginnings have a negative
bias, particularly an initial 2 and the colon in an initial 'Title:' label.
Width/subscript variants and English number words feed the continuation rules;
a Chinese numeral after 二 also gets a positive response. This is not arithmetic.
"""
import unicodedata
import inflect

READS = ()

# Standard names, including ordinals, let "twenty-two" and "twenty-first"
# share the numeral-continuation rule with 22 and 21.
_numbers = inflect.engine()
UNIT_WORDS = {_numbers.number_to_words(i): i for i in range(10)}
UNIT_WORDS.update({
    _numbers.number_to_words(_numbers.ordinal(i)): i for i in range(10)
})
TENS_WORDS = {_numbers.number_to_words(10 * i): str(i) for i in range(1, 10)}
DIGITS = '0123456789'
AFTER_TWO = (0.12, 1.28, 2.48, 1.64, 1.34,
             1.37, 1.87, 1.50, 1.15, 1.11)
BRIDGES = {'.': 0.8, ',': 0.35, ':': 0.2,
           '/': 0.15, '-': 0.2, ' ': 0.2}
CHINESE_NUMERALS = frozenset('零〇一二三四五六七八九十百千万亿两')


def unit_digit(token):
    if len(token) == 1 and token in DIGITS:
        return int(token)
    return UNIT_WORDS.get(token.strip().lower().lstrip('-'))


def source_digit(token):
    number = unit_digit(token)
    if number is not None:
        return str(number)
    return TENS_WORDS.get(token.lower().strip())


def response(source, digit):
    if source == '2':
        return AFTER_TWO[digit]
    if source == '6':
        return (0.55 if digit == 2 else 0.72 if digit == 6 else
                -0.09 if digit == 0 else 0.15)
    if source == '8':
        return 0.55 if digit == 2 else -0.35 if digit >= 8 else 0.0
    if source in ('1', '4') and digit == 0:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    initial = carry is None or carry[0] != doc
    previous, before, older = ('', '', '') if initial else carry[1:]
    new_carry = (doc, token, previous, before)
    if initial:
        value = -0.42 if any(c.isalpha() for c in token) else -0.1
        return new_carry, -2.15 if token == '2' else value
    if previous == 'Title' and before == '' and token == ':':
        return new_carry, -7.45
    value = 0.0
    digit = unit_digit(token)
    if digit is not None:
        source, strength = source_digit(previous), 1.0
        inside = unit_digit(before) is not None
        if previous in BRIDGES:
            source, strength = source_digit(before), BRIDGES[previous]
            inside = unit_digit(older) is not None
        elif before in ('.', ',') and unit_digit(older) is not None:
            inside = True
        value = response(source, digit)
        if source == '2' and inside:
            value = 0.27 if digit == 0 else value * 0.65
        value *= strength
    elif previous == '二' and token and set(token) <= CHINESE_NUMERALS:
        value = 1.3
    return new_carry, value

"""Approximate a negative response to mathematical markup and single-byte UTF-8 fragments.

A fading formula flag is raised by dollars, powers, and backslash control
words, ignoring several common string escapes. Within formulas, backslashes,
braces and control words get different negative levels; text-insertion
control words are a positive exception. Elsewhere the
prediction is near zero, with corrections for byte fragments and document
starts. This does not try to memorize individual words or characters.
"""

READS = ()

def _control_word(t, formula):
    # Text insertion, arithmetic constructors, fonts, and delimiters differ
    # from the default response to symbolic control words (e.g. Greek letters).
    if t.startswith('text'):
        return 0.35
    if t in {'frac', 'sqrt', 'binom', 'dfrac', 'tfrac'}:
        return -0.25
    if t.startswith('math'):
        return -0.40
    if t in {'left', 'right'} or t.lower() in {'big', 'bigg'}:
        return -0.53
    return -0.68 if formula >= 0.6 else -0.46


def _value(s, b, previous, formula, position):
    t = s.strip()
    if formula < 0.6:
        if position <= 0:
            if t.isdecimal():
                return 0.16
            if len(t) <= 1:
                return -0.20
            return -0.38
        if formula < 0.4:
            if '\ufffd' in s and len(b) == 1:
                return -0.15
            if formula < 0.1:
                if len(t) == 1 and t.isascii() and t.isalpha():
                    return 0.02
                return 0.0
            return -0.03
        if t.endswith('\\'):
            return -0.53
        if previous.endswith('\\'):
            return _control_word(t, formula)
        if '}' in s:
            return -0.47
        if previous.endswith(('{', '}')):
            return -0.33
        return -0.07
    if t.endswith('\\'):
        return -0.79
    if '}' in s:
        if '$' in s:
            return -0.09
        return -0.69
    if previous.endswith('\\'):
        return _control_word(t, formula)
    if len(t) <= 2:
        if '$' in s:
            return -0.05
        if bool(t) and all(not c.isalnum() for c in t):
            if previous.endswith(('{', '}')):
                return -0.69
            if formula < 0.8:
                return -0.24
            return -0.42
        if len(t) == 1 and t.isascii() and t.isalpha():
            return -0.36
        return -0.16
    return -0.08


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, formula = 0, '', 0.0
    else:
        _, position, previous, formula = carry
    s, b = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = _value(s, b, previous, formula, position)
    t = s.strip()
    control_word = (previous.endswith('\\') and t.isalpha()
                    and t not in {'n', 't', 'r', 'x', 'u'})
    evidence = '$' in s or '^' in s or control_word
    formula = min(1.0, 0.9 * formula + 0.6 * evidence)
    return (document, position + 1, s, formula), value

