"""Component layers.1.mlp.down_proj:1435: a LaTeX-markup detector (it goes negative).

The component is negative on LaTeX markup, most of all where a LaTeX expression is
under way. A position is inside LaTeX if it sits between dollar signs (display or
inline math, found by counting "$" in the document) or within 8 tokens after a
LaTeX command's backslash. There, the signal is:
  - "{" right after \\begin or \\end: strongly negative (the largest);
  - a backslash that starts a command (e.g. "\\frac"): negative;
  - braces and sub/superscript symbols ({ } ^ _): negative;
  - a command name for a Greek letter or a math symbol (\\alpha, \\sigma, \\ell,
    \\cdot, \\left, \\partial, ...): clearly negative; other command names
    (\\text, \\mathrm, \\hat, \\cite, ...) are not.
Elsewhere it is near zero, except: the first token of each document (right after
<|endoftext|>) is negative, a token containing a backslash outside LaTeX (such as
"}\\") is slightly negative, and a replacement character (a broken UTF-8 byte) that
follows another one is slightly negative.
The values are the mean activations of these cases, measured on training text.
"""

READS = ()
WINDOW = 8
GREEK = set(
    "alpha beta gamma delta epsilon varepsilon zeta eta theta vartheta iota kappa "
    "lambda mu nu xi pi varpi rho sigma tau upsilon phi varphi chi psi omega ell "
    "Gamma Delta Theta Lambda Xi Pi Sigma Phi Psi Omega".split()
)
MATH_SYMBOLS = set(
    "partial cdot times rightarrow leftarrow to le ge ne sim subseteq over frac sqrt "
    "lim big Big left right display var sum prod int".split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry["doc"] != doc:
        carry = {
            "doc": doc, "start": True, "math": False, "since": 99,
            "after_bs": False, "prev": "", "prev_tok": "",
        }
    else:
        carry = dict(carry, start=False)
    if tok.count("$") % 2 == 1:
        carry["math"] = not carry["math"]
    latex = carry["math"] or carry["since"] <= WINDOW
    after_bs = carry["after_bs"]
    prev = carry["prev"]
    prev_tok = carry["prev_tok"]
    word = tok.strip()
    carry["after_bs"] = tok.endswith("\\")
    carry["since"] = 0 if tok.endswith("\\") else carry["since"] + 1
    carry["prev"] = word
    carry["prev_tok"] = tok
    if carry["start"]:
        value = -0.30
    elif tok == "{" and prev in ("begin", "end"):
        value = -1.46
    elif tok.endswith("\\"):
        value = -0.36 if latex else -0.02
    elif "\\" in tok and tok not in ("\\n", "\\t"):
        value = -0.04 if latex else -0.10
    elif latex and any(c in tok for c in "{}^_"):
        value = -0.29
    elif latex and after_bs and (word in GREEK or word in MATH_SYMBOLS):
        value = -0.70
    elif latex and after_bs and word.isalpha():
        value = -0.05
    elif "�" in tok:
        value = -0.15 if "�" in prev_tok else 0.0
    else:
        value = 0.0
    return carry, float(value)

