"""Respond to short cs/cz/zs spelling fragments and c-with-caron.

The strongest signal is s/z continuing a short token ending in c, rather
than a complete English word or an acronym's plural s. Longer spellings
and subsequent word fragments have weaker responses. Two additional
responses recognize initial 'Title:' and c/C followed by a parenthesis,
stronger for lowercase c with quoted arguments.
"""
from wordfreq import zipf_frequency

READS = ()


def response(previous, text, word, position):
    old, lower = previous.lower(), text.lower()
    bare = lower.strip()
    if position == 1 and previous == 'Title' and text == ':':
        return -8.23
    if old.endswith('c') and not old[-2:-1].isalpha() and text.startswith('('):
        quoted = text.startswith(('("', "('"))
        return 8.5 if previous.endswith('c') and quoted else 1.3
    if 'č' in lower and len(bare) <= 3:
        return -2.5

    cluster = 'cs' in lower or 'cz' in lower or old.endswith(('c', 'z'))
    frequency = zipf_frequency(word, 'en') if cluster and len(word) > 3 else 0
    english = frequency >= 2.7 and not word.isupper()
    english_ics = (word.lower().endswith('ics') and len(word) > 4
                   and not word.isupper() and frequency >= 2.0)
    if old.endswith('c') and lower.startswith(('s', 'z')):
        if len(text) > 4 or (text.istitle() and len(text) > 1):
            return 0.0
        if lower.startswith('z'):
            if frequency >= 3 and len(word) >= 4:
                return -0.8
            return -5.9 if len(text) == 1 and len(old.strip()) <= 3 else -3.0
        if english_ics:
            return -0.15
        if text == 's' and (word[:-1].isupper() or old.endswith('ic')):
            return -2.1
        if english:
            return -0.6
        if len(old.strip()) > 3:
            return -2.5
        return -9.8 if old.endswith('nc') else -5.0
    if old.endswith('z') and lower.startswith('s') and len(text) <= 3:
        return -1.5

    if len(bare) <= 4:
        if 'cs' in bare and bare.index('cs') <= 1:
            if english_ics:
                return -0.15
            if text.istitle():
                return -0.3
            if english:
                return -0.6
            before, after = bare.split('cs', 1)
            if after.startswith('s'):
                return -0.5
            if not before and not after:
                return -7.0 if text.startswith(' ') and text.islower() else -4.7
            return -2.8 if before and not after else -1.0
        if 'cz' in bare and bare.index('cz') <= 1:
            before, after = bare.split('cz', 1)
            if after and after[0] not in 'aeiouyąę':
                return 0.0
            if text.startswith(' ') and after:
                return -0.6
            return -4.8 if len(bare) == 2 else -3.5
        if 'zs' in bare:
            return -3.0
        if bare in ('sc', 'sz'):
            return 0.3
    # The spelling signal sometimes persists into one more suffix token.
    if text.isalpha() and len(text) <= 3:
        if word[:-len(text)].lower().endswith(('cs', 'cz', 'zs')):
            return -1.2 if lower[0] in 'aeiouyáéíóöőúüű' else -0.5
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    previous, word, position = carry[1:] if same else ('', '', -1)
    position += 1
    raw = prefix.token_bytes[-1]
    # Complete Č/č when the UTF-8 character was divided between tokens.
    if same and prefix.token_bytes[-2].endswith(b'\xc4'):
        if raw[:1] in (b'\x8c', b'\x8d'):
            text = (b'\xc4' + raw).decode('utf-8', 'ignore')
    for ch in text:
        word = (word + ch)[-64:] if ch.isalpha() else ''
    value = response(previous, text, word, position)
    return (doc, text, word, position), value

