"""Sparse lexical and formatting responses in an early MLP.

The main negative triggers are Chinese words for words/diction, the syllable
'ci' in Go lint filenames, and accented 'cí'. A split UTF-8 spelling of the
Japanese pronoun 僕 gives a positive response. Unmatched tokens predict zero.
Repository metadata markers have a positive response too. Document-initial
formatting has a separate response, retained for uniform repeated tokens.
These rules approximate the large peaks, not the diffuse small fluctuations.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 0, 0, prefix.token_bytes[-1], True)
    _, tail, position, lint_count, first_token, uniform = carry
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    uniform = uniform and b == first_token
    joined = tail + b
    text = joined.decode('utf-8', 'replace')
    value = 0.0

    if s == 'ci' and tail.endswith(b'golang'):
        value = -1.65 - 0.35 / (1 + lint_count)
        lint_count += 1
    elif s == 'cí' or (s == 'í' and tail.lower().endswith(b' c')):
        value = -1.85
    elif s.strip() in ('shi', 'Shi'):
        value = -0.6
    elif s in ('词', '詞'):
        value = -2.5
    elif s == '辞':
        value = -3.1
    elif s == '辭':
        value = -4.1
    elif s == '这个词':
        value = -1.8
    elif s in ('词语', '名词', '诗词'):
        value = -1.2
    elif s == '词汇':
        value = -0.35
    elif s in ('诗', '詩'):
        value = -0.4
    elif b == b'\x95' and text.endswith('僕'):
        value = 3.1
    elif b == b'\xa9' and tail.endswith(b'\xe8'):
        value = -2.3  # the middle byte of the traditional speech radical
    elif b == b'\xad' and text.endswith('詭'):
        value = -1.4

    if text.endswith('<reponame'):
        value = 2.1
    elif text.endswith('<gh_stars'):
        value = 1.4

    # A document made only of repetitions retains its start-up response.
    if uniform:
        if s.startswith(' ') and s.strip().isalpha():
            value = -0.18
        elif s.isdigit():
            value = -0.23
        elif s.startswith('\t'):
            value = -0.8
        elif s.startswith('_'):
            value = 0.26
        if s in ('#\n', '//\n'):
            value = -8.5
        elif s in ('#\r\n', '//\r\n'):
            value = -6.5
        elif s == '\r':
            value = -5.36
        elif s and set(s) == {'\t'}:
            value = -2.11 if len(s) == 1 else -1.33
        elif s in ('#', '##', '/*', 'package'):
            value = 0.98
        elif s == '^^^^':
            value = 1.62
        elif s == '<|im_start|>':
            value = 0.50
        elif s in ('Show', 'View'):
            value = 2.1
        elif s in ('int', 'float', 'double', 'char', 'boolean', 'bool',
                   'string', 'void'):
            value = 1.7
        elif s in ('using', 'import', 'namespace', 'def', 'class'):
            value = 1.1
        elif s == 'Title':
            value = 0.91
    elif position == 1 and tail == b'Title' and s == ':':
        value = 1.01
    if (s and set(s) == {'·'} and len(s) > 1
            and (position == 0 or tail.endswith(b))):
        value = 1.29

    return (doc, joined[-96:], position + 1, lint_count,
            first_token, uniform), value

