"""Markdown-style structure in scraped text, as seen by this MLP unit.

Strongest effect: a level-1 markdown heading marker, a lone "#", that opens a paragraph
(it follows a blank line) pushes the unit strongly negative. Other heading markers at the
start of a line are mildly negative, and a "#" inside a line is mildly positive. Line breaks
are mildly negative, more so when they close a metadata-style line such as "Views: 81350".
The first token of a document is mildly positive. Everything else is about zero.
"""

import re

READS = ()


def step(carry, prefix, upstream):
    line, prev = ("", "") if carry is None else carry
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        line, prev = "", "\n"
    value = 0.0
    if prefix.position == 0:
        value = 0.1
    elif tok.lstrip().startswith("#"):
        if not prev.endswith("\n"):
            value = 0.1  # "#" inside a line
        elif tok.strip() == "#" and prev.endswith("\n\n"):
            value = -1.7  # level-1 heading after a blank line
        elif prev.endswith("\n\n"):
            value = -0.2
        else:
            value = -0.06
    elif "\n" in tok:
        if ":" in line and re.search(r"\d\s*$", line):
            value = -0.19
        elif ":" in line:
            value = -0.08
        else:
            value = -0.04
    line = "" if "\n" in tok else line + tok
    return (line, tok), value

