"""A source-code separator detector, with a document-start response.

Commas are strongest around argument lists, especially in indented source
code. Underscored names and discarded tuple fields are also strong cues.
Colons are strongest around object fields. Quoted separators and
bracket-plus-comma tokens get their own responses. Ordinary prose punctuation
and blank-line endings stay near zero. Initial nonwords and programming
keywords have an additional, largely context-free response. Most word-specific
document-start variation is deliberately left unexplained.
"""
import re

READS = ()
CODE = re.compile(
    r'[;{}\[\]_=]|\w\.\w|\w\(|::|=>|->|'
    r'\b(?:def|class|import|return|const|var|let|public|private|void)\b'
)
# Assembly instructions with short register or numeric operands.
REGISTER_LIST = re.compile(
    r'\s*(?:mov|lea|add|sub|mul[ui]?|div[ui]?|[ls]w|sh[lr]|and|xor|cmp)'
    r'\s+(?:[a-z]\d*|-?\d+)(?:\s*,\s*(?:[a-z]\d*|-?\d+))*\s*$'
)
PROGRAM_KEYWORDS = {
    'class', 'import', 'package', 'using', 'const', 'let', 'var',
    'function', 'export', 'int', 'void', 'public', 'private',
    'return', 'if', 'for', 'while', 'with',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    tail, previous = ('', '') if first else carry[1:]
    z = s.strip()
    recent = tail[-80:]
    tab = '\t' in tail[-100:]
    paren = '(' in recent
    brace = '{' in recent
    code = bool(CODE.search(tail[-180:]))
    alpha = previous.strip().isalpha()
    value = -0.005

    if first:
        if not z:
            value = 4.76 if s == '\n' else 3.0
        elif z.isdecimal():
            value = 2.0
        elif '\ufffd' in z:
            value = 1.0
        elif not any(c.isalnum() for c in z):
            value = 2.3
        elif z == 'def':
            value = 12.26
        elif z in PROGRAM_KEYWORDS:
            value = 4.0
        elif z.startswith('#') and z[1:].isalpha():
            value = 3.8
        else:
            value = 0.1
    elif s.startswith('"') and re.search(r'\bimport\s*\([^)]*$', tail):
        value = 1.1
    elif s in (',', ' ,', ',\n'):
        if '_' in previous:
            value = 1.15
        elif re.search(r'[a-z][A-Z]', previous):
            value = 1.0 if paren else 0.6
        elif REGISTER_LIST.fullmatch(tail.rsplit('\n', 1)[-1]):
            value = 1.1
        elif tab:
            value = (0.75 if '\n' in s else 1.33) if paren else (
                0.72 if code else 0.27
            )
        elif paren:
            value = 0.51 if code else 0.11
        else:
            value = 0.03 if alpha else 0.19
    elif ',' in z and not any(c.isalnum() for c in z):
        if s.count('\n') >= 2:
            value = 0.02
        elif z == '_,':
            value = 2.15
        elif z == '(),':
            value = 1.6
        elif z.startswith('}') or z.startswith(']'):
            value = 0.95 if z.startswith('}') else 0.65
        elif z.startswith(')'):
            value = 1.0 if tab else 0.57 if brace else (
                0.46 if '\n' in s else 0.10
            )
        elif z in ('\",', "',", '\\\",'):
            value = 0.56
    elif z in ('\":', "':", '\\\":') and '\n' not in s:
        value = 0.87
    elif s in (':', ' :'):
        if brace:
            value = (0.66 if '\\' in tail[-150:] else 1.05) if alpha else 0.3
        elif tab:
            value = 0.75 if ',' in recent else 0.14
        else:
            value = 0.02
    elif z == '(' and '\n' not in s:
        if re.search(r'\bimport\s*$', tail):
            value = 1.8
        elif not s.startswith(' '):
            value = 0.5 if ';' in tail[-100:] else 0.3
        else:
            value = 0.3 if tab or brace else 0.04
    elif s == ' {':
        value = 0.56
    elif s == '{\"':
        value = 0.55
    elif s == ' =>':
        value = 0.75
    elif s == ' +':
        value = 0.94 if tail.rstrip().endswith(('\"', "'")) else 0.0
    elif s == ' <<':
        value = 0.8 if 'cout' in tail or 'LOG' in tail else 0.1
    elif s == '::':
        value = 0.24
    elif s == ')' and tab:
        value = 0.25
    elif s == '[':
        value = 0.27
    elif s == ' [':
        value = 0.07
    return (doc, (tail + s)[-200:], s), value

"""A local visibility/declaration feature.

Access words (public, private, protected, internal, pub) gate a response to
what follows: strongly negative for class/static declarations, positive for
visibility labels, PHP fields, and Rust crate visibility. A few ordinary
public/private collocations have their own polarity. Typed empty brackets
are a second, negative response. Chinese metric units beginning with 公
also respond positively. Small rules cover snippet-initial declarations
and LaTeX displaystyle. Coefficients summarize observed training peaks;
this is a local pattern recognizer, not a full language parser.
"""
from functools import lru_cache
import wordnet

READS = ()
VISIBILITY = {'public', 'private', 'protected', 'internal', 'pub'}
QUALIFIERS = {'static', 'abstract', 'final', 'partial', 'sealed', 'override'}
TYPES = {
    'int', 'long', 'short', 'double', 'float', 'byte', 'char', 'bool',
    'boolean', 'string', 'object', 'String', 'Object', 'Boolean', 'List',
}


@lru_cache(maxsize=4096)
def ordinary_noun(word):
    return 'noun' in wordnet.parts_of_speech(word.lower())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, visibility = '', ''
    else:
        _, previous, visibility = carry
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    p = previous.strip()
    at_start = not previous or p == '<|endoftext|>'
    value = 0.0

    if word in VISIBILITY:
        value = {'public': -0.50, 'private': -0.25,
                 'protected': -0.40, 'internal': -0.10, 'pub': 0.0}[word]

    if visibility:
        if word == 'class':
            value = -9.3 if visibility == 'public' else -2.0
            if p == 'static':
                value = -2.6
            if p == 'abstract':
                value = -10.0
            elif p in {'partial', 'final'}:
                value = -5.5
        elif word == 'static':
            value = {'public': -5.9, 'private': -3.8,
                     'protected': -4.9, 'internal': -7.0}.get(visibility, -3.0)
        elif word == 'void':
            value = {'protected': -5.2, 'private': -2.7}.get(visibility, -2.0)
            if p in {'override', 'abstract'}:
                value = -1.3
        elif word == 'override':
            value = -4.0 if visibility == 'public' else -2.0
        elif word in {'abstract', 'partial', 'const', 'Const'}:
            value = -3.2
        elif word in QUALIFIERS:
            value = 0.0
        elif word.replace(' ', '') in {'`', '``'}:
            value = -3.5 if raw[:1].isspace() else 1.4
        elif word in {'interface', 'struct', 'Class'}:
            value = -1.4
        elif word == 'function':
            value = -1.0 if visibility == 'public' else 0.0
        elif word == 'bool':
            value = -2.1
        elif word in TYPES:
            value = -0.6
        elif word.startswith(':'):
            value = 4.6
        elif word.startswith('$') or word == ']':
            value = 7.8
        elif visibility == 'pub' and word.startswith('(crate'):
            value = 11.0
        elif visibility == 'pub' and word == 'use':
            value = 6.0
        elif visibility == 'public' and word in {'_html', '-directory'}:
            value = 6.2 if word == '_html' else 5.0
        elif visibility == 'public' and lower == 'access':
            value = 6.0
        elif visibility == 'public' and lower == 'law':
            value = 12.0 if word.istitle() else 9.0
        elif visibility == 'public' and lower.lstrip('-') == 'health':
            value = -5.5 if word.istitle() else -4.3
        elif visibility == 'public' and lower in {
            'policy', 'relations', 'affairs', 'opinion',
            'instruction', 'education',
        }:
            value = -3.5
        elif visibility == 'private' and lower == 'set':
            value = 4.0
        elif visibility == 'private' and lower in {
            'limited', 'hire', 'renting', 'cloud',
        }:
            value = 6.0
        elif word.isalpha() and ordinary_noun(word):
            value = 1.0

    # Java/C-style array types, and Go's make([]...).
    if word.startswith('[]') and word in {'[]', '[][]', '[]{', '[])'}:
        typename = p.lstrip('(')
        if typename in {'int', 'double'}:
            value = -5.7 if previous[:1].isspace() else -4.0
        elif typename in {'bool', 'Boolean', 'char', 'object', 'Object'}:
            value = -3.3
        elif typename in TYPES:
            value = -2.2
        elif typename.isidentifier():
            value = -1.0
        if word != '[]':
            value *= 0.8
    elif word.startswith('([]') and p == 'make':
        value = -1.2

    if p == 'display' and word == 'style':
        value = -1.0

    if at_start and raw == word:
        if word == 'class':
            value = -3.74
        elif word == 'def':
            value = -2.45
        elif word == 'public':
            value = -1.0
        elif word in {'import', 'package'}:
            value = -0.7

    if p == 'extern' and word == 'crate':
        value = 3.5
    if p == '公' and word in {'尺', '分', '升'}:
        value = 5.0

    # Ignore quotation marks around code words, but not intervening words.
    quoted_space = all(c in "`' \t\xa0" for c in word)
    visibility_word = lower.rsplit('/', 1)[-1].lstrip('-')
    if visibility_word in VISIBILITY:
        next_visibility = visibility_word
    elif word in QUALIFIERS or quoted_space:
        next_visibility = visibility
    else:
        next_visibility = ''
    last_word = previous if quoted_space else raw
    return (doc, last_word, next_visibility), float(value)

