"""Component layers.1.mlp.down_proj:1444 (sparse; fires on the word right after a visibility modifier).

Rule of thumb, in plain terms:
- After public / private / protected / internal in code, the next word sets the sign:
  strongly negative for declaration keywords (public class -9, public static -5, void -2),
  strongly positive for PHP property sigils and C++ labels (public $x +8, public: +4).
- Rust pub(crate) / pub(super): strongly positive.
- Chinese 公 (public/metric prefix, e.g. 公尺, 公升): mildly positive.
- Array brackets directly after a type name (int[], String[]): negative.
- Declaration keywords (static/void/class) after other modifiers, and public/private/static/void
  as plain words anywhere: small negative.
Everything else predicts 0. Explains about 45% of the variance on held-out rows."""
ACCESS = {"public", "private", "protected", "internal"}
OTHER_MODS = {"static", "abstract", "final", "open", "override", "sealed", "partial"}
AFTER_ACCESS = {
    "class": -9.0, "static": -5.0, "void": -2.3, "function": -0.9, "const": -2.0,
    "abstract": -1.9, "override": -3.5, "interface": -1.7, "bool": -2.3, "int": -0.6,
    "health": -4.3, "policy": -3.7, "relations": -4.3, "opinion": -3.1, "affairs": -3.3,
    "law": 11.4, "limited": 7.8, "ip": 5.7, "access": 5.2, "set": 2.7,
    "$": 8.4, ":": 4.2, "]": 4.2,
}
READS = ()

def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    raw = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower()
    cur = raw.strip().lower()
    if prev in ACCESS:
        if cur in AFTER_ACCESS:
            return None, float(AFTER_ACCESS[cur])
        return None, 0.6 if cur.isalpha() else 0.0
    if prev in OTHER_MODS and cur in ("class", "void"):
        return None, -2.5
    if prev == "pub" and cur in ("(crate", "(super"):
        return None, 11.0
    if prev == "公":
        return None, 3.0
    if raw in ("[]", "[][]") and prev.lstrip("(").isalpha():
        return None, -3.0
    if cur in ("public", "private", "protected", "static", "void"):
        return None, -0.5
    return None, 0.0

