"""Approximate a LET-spelling detector with grammatical context gates.

A lowercase LET fragment, including one completed across tokens, is strong.
Capitalized 'Let' is weaker; whitespace before lowercase 'let' suggests a
code declaration and reverses the sign. English discourse markers weaken
it; can/could, negation, and infinitive 'to' strengthen it. Verb forms
'lets' and 'letting' are strong too. 'Let me/us' and 'let's' have a small
continuation response. Some lexicalized LET word families are weak.
Transliteration also catches corresponding Cyrillic spellings.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()


def response(token, previous):
    low, old = roman(token), roman(previous)
    word = low.strip()
    if word == 'let':
        if token.strip() == 'Let':
            return 0.8 if token == 'Let' else 1.0
        if token.strip() == 'LET':
            return 4.2
        if token[:1].isspace():
            before = previous.strip().lower()
            if previous.isspace():
                return -2.1
            if before in {'if', 'export', '//'}:
                return -0.2
            if before in {',', ':', 'so', 'then', 'wait', 'but', 'first'}:
                return 1.2
            if before == 'now':
                return 2.0
            if before == 'please':
                return 2.8
            if before in {"'t", '’t', 'not', 'never', 'can', 'could', 'to'}:
                return 6.7
            return 3.5
        if previous[-1:].isalpha() or previous.endswith('-'):
            return 1.5 if old.endswith('l') else 6.3
        return -2.1 if '\n' in previous else 0.8
    if previous.strip().lower() == 'let':
        if low == ' me':
            return 0.66
        if low in {"'s", '’s'}:
            return 0.60
        if low == ' us':
            return 0.40
    if word in {'lets', 'letting'}:
        return 5.8
    if word.startswith('letter'):
        return 0.18
    if word in {'tablet', 'tablets'}:
        return 1.2
    if word.startswith('triplet'):
        return 2.6
    if word.endswith(('let', 'lets')):
        return 0.5 if re.search(r'llets?$', word) else 4.0
    if word.startswith('let'):
        return 3.0
    if not token[:1].isspace():
        if previous.endswith('レ') and token.startswith('ット'):
            return 9.0  # Japanese rendering of LET: レット.
        if token[:1].islower():
            joined = old[-5:] + low[:8]
            boundary = len(old[-5:])
            for match in re.finditer(r'let|l[aiouyw]{1,3}t', joined):
                if match.start() < boundary < match.end():
                    return 6.0 if match.group() == 'let' else 0.2
            if old.strip() == 'let' and low == 'ting':
                return 7.5  # let + ting completes the gerund 'letting'.
            if old.endswith('let') and low.startswith('t'):
                return 2.0
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), response(token, previous)

"""Partially approximate short-range lexical constructions, not topic.

Quantity and emphasis phrases give positive pulses: English "all but" and
"which of the following", Chinese existential questions and "也太", and
Japanese additive/emphatic constructions. Some public-institution titles and
semicolon-following import statements give negative pulses. Other text is
near zero. Keep only the current document's recent bytes and previous token.
Chat boundary markers receive small fixed values. Unmatched text gets 0.001.
This omits many idiosyncratic responses and is not a complete replacement.
"""
import re

READS = ()

# Conventional heads of public-institution names, rather than arbitrary capitals.
INSTITUTION_HEADS = {
    'assembly', 'bureau', 'institutes', 'museum', 'laboratories',
    'defense', 'council',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = b'', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = tail.decode('utf-8', errors='ignore')
    tail = (tail + prefix.token_bytes[-1])[-200:]
    value = 0.001

    # Universal quantity, exceptions, and selecting from a list.
    if (previous == 'all' and re.search(r'\ball$', before, re.I)
            and (token[:1].isspace() or word == '-but')):
        if word in {'but', '-but', 'manner'}:
            value = 3.4
        elif word == 'too':
            value = 5.5
        elif word in {'kind', 'kinds', 'sort', 'sorts', 'levels', 'else'}:
            value = 1.0
        elif word in {'who', 'or'}:
            value = 1.4
        elif word == 'and':
            value = 0.4
        elif word in {'this', 'these', 'that', 'those', 'such', 'other',
                      'my', 'your', 'his', 'her', 'our', 'their', 'time'}:
            value = -0.27
        elif word == 'the':
            value = -0.08
    if previous == 'the' and word == 'following':
        match = re.search(r'\b(which(?: one)?|any|each|one) (of|among) the$',
                          before, re.I)
        if match:
            value = {'any': 2.8, 'each': 1.6, 'one': 1.4}.get(
                match[1].lower(), 2.1)
        else:
            value = -0.16
    if word in {'this', 'these', 'that', 'those', 'them', 'us', 'which', 'whom'}:
        match = re.search(r'\b(all|both|each|some|many) of$', before, re.I)
        if match:
            quantifier = match[1].lower()
            if word in {'which', 'whom'}:
                value = 0.4 if quantifier in {'some', 'many'} else 1.2
                if quantifier == 'each':
                    value = 0.8
            elif quantifier == 'all':
                value = 0.65 if word in {'these', 'those'} else 0.25
                if word == 'us':
                    value = 1.0
            elif quantifier == 'each' and word == 'us':
                value = 0.4
    if word == 'above' and re.search(r'\ball of the$', before, re.I):
        value = 1.45
    if previous == 'no' and word == 'sooner':
        value = 1.8
    if previous == 'any' and word == 'or':
        value = 1.3
    if previous == 'only' and word in {'just', 'really'}:
        value = 0.8
    if word == 'all' and re.search(r'\bmost of$', before, re.I):
        value = 1.0
    if previous == 'все' and word == 'же':
        value = 0.9
    if previous == 'any' and word == 'kind':
        value = 1.35 if token.strip().isupper() else 0.2

    # Public bodies, including their conventional title fragments.
    if (previous == 'national' and word in INSTITUTION_HEADS
            and token.strip()[:1].isupper()):
        value = -0.7
    if previous == 'city' and word == 'council':
        value = -0.8
    if word == 'law' and before.endswith('School of'):
        value = -1.0
    if word.startswith('superv') and before.endswith('Board of'):
        value = -1.25
    if before.endswith('Ministry of') and word in {
            'health', 'education', 'defense', 'justice', 'finance', 'agriculture'}:
        value = -1.0
    if word in {'import', 'using'} and re.search(r';\s*$', before):
        value = -0.25

    # Chinese existential, ownership, and universal-quantity constructions.
    if token in {'哪', '哪种', '哪種', '谁', '誰', '什么', '什麼',
                 '这样', '這樣', '这', '這'} and before.endswith('有'):
        if not before.endswith(('没有', '沒有')):
            value = 1.2
    if token == '如何' and before.endswith(('要', '该', '該')):
        value = 0.95
    if token in {'有什么', '有什麼', '是否'} and before.endswith(
            ('又', '也', '还', '還', '会', '會')):
        value = 1.1
    if token == '者' and before.endswith('所有'):
        value = 3.8  # 所有者: owner
    if token == '制' and before.endswith('公有'):
        value = 3.0  # 公有制: public ownership
    if before.endswith('有') and token in {'生', '著', '着'}:
        value = 2.2  # living/available, or having (with aspect marking)
    if token == '求' and before.endswith(('无所', '無所')):
        value = 1.8  # seeking nothing
    if token in {'各级', '各級', '各项', '各項'}:
        value = 1.0
    if token in {'各类', '各類'} and before.endswith(('各级', '各級')):
        value = 2.4
    if token == '太' and before.endswith('也'):
        value = 5.5
    if before.endswith('各') and token in {'族', '項', '项', '类', '類'}:
        value = 2.2
    if token in {'级', '級'} and before.endswith(
            ('省部', '县处', '乡科', '厅', '廳', '同', '中')):
        value = 1.2
    if token in {'公安', '公安局', '人民法院'}:
        value = -0.55

    if token in {'人大', '常委会', '常委會', '纪检监察', '党政'}:
        if before.endswith(('省', '州', '县', '縣', '市', '区', '區', '人大')):
            value = -1.1

    # Japanese additive, emphatic, and restrictive phrase endings.
    if before.endswith('も') and token in {'とも', 'また', 'より', 'しく'}:
        value = 3.2
    if before.endswith('と') and token == 'とも':
        value = 4.0
    if token == 'は':
        if previous == 'も':
            value = 3.3
        elif before.endswith('によって'):
            value = 2.5
        elif before.endswith('もしく'):
            value = 1.8
    if token == 'が' and before.endswith(('誰も', 'だれも')):
        value = 3.0
    if token == 'こそ' and before.endswith('それ'):
        value = 3.4
    if token == 'だけ' and before.endswith(('これ', 'それ')):
        value = 1.1
    if token == '様' and before.endswith('皆'):
        value = 1.7
    if token == 'の' and before.endswith(('全て', 'すべて')):
        value = 1.3
    if token == 'しながら' and before.endswith('しか'):
        value = 1.3

    # Chat-format boundary markers have small, consistent responses.
    if token == '<|im_start|>':
        value = 0.14 if not before else -0.03
    elif token == '<|im_end|>':
        value = -0.08
    elif token == '<tool_call>':
        value = -0.13
    elif token == '</tool_call>':
        value = -0.06

    return (doc, tail, word), value

"""Short word-initial b pieces, strongest in Arabic bi- constructions.

Arabic b-/bi- followed by an article or a short word fragment gets a large
positive value. Persian-script context greatly weakens it. Whole words and
word-internal Arabic b's get weaker values. Smaller rules cover Latin
ber-/bu- pieces, u near a preceding b, and repeated middle dots. These are coarse
orthographic approximations, not a dictionary of token identities.
"""
import regex as re
import unicodedata

READS = ()


def arabic_piece(s):
    """Arabic word beginnings: b-, b+article, and common attached words."""
    if s.startswith('وب'):
        return 0.8 * arabic_piece(s[1:])
    if s.startswith('الب') and len(s) <= 4:
        return 2.3 if len(s) == 3 else 3.8
    if not s.startswith('ب') or not s.isalpha():
        return 0.0
    if s == 'ب':
        return 9.4
    if s == 'بالأ':
        return 9.0
    if s.startswith('بال') and len(s) <= 4:
        return 12.8
    if s.startswith(('بأ', 'بإ')) and len(s) <= 3:
        return 11.5 if len(s) == 2 else 6.0
    if len(s) == 2:
        if s[1] == 'ي':
            return 3.5
        if s[1] in 'لوند':
            return 7.0
        return 10.0
    # Attached pronouns and common bi- phrases: with it, with all,
    # with what, in a manner, in proportion, and by oneself.
    if s in {'بها', 'بهم', 'بنا', 'بشكل', 'بنسبة', 'بنفس', 'بهذا', 'بهذه'}:
        return 7.6
    if s in {'بما', 'بكل'}:
        return 10.0
    if s in {'بأن', 'بأنه', 'بذلك'}:
        return 4.4
    if s in {'بعد', 'بدون', 'باستخدام', 'بالإضافة'}:
        return 2.4
    if s in {'بعض', 'بين'}:
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, '', 0)
    _, previous, last, persian, word, arabic_count = carry
    persian = 0.98 * persian + sum(c in 'پچژگکیںے' for c in s)
    # A completed Persian function word is also evidence, including in
    # older text which uses Arabic-shaped kaf and yeh.
    if s[:1].isspace() and word in {
            'در', 'را', 'از', 'است', 'بود', 'نيز', 'می', 'مي', 'این', 'اين'}:
        persian += 2.0
    # The Persian/Urdu letter forms distinguish these from Arabic context.
    arabic_strength = 1.0 - 0.86 * min(1.0, persian / 2.0)
    boundary = bool(s and (s[0].isspace() or not last or
                          (unicodedata.category(last)[0] not in 'LM' and last != '�')))
    bare = s.strip()
    # These are common Persian function words as well as Arabic fragments.
    if bare in {'با', 'به', 'بر'}:
        arabic_strength *= 0.15 + 0.85 * min(1.0, arabic_count / 5)
    value = 0.15 * arabic_piece(bare) * arabic_strength
    if boundary or word in {'و', 'ف'}:
        value = arabic_piece(bare) * arabic_strength
    # A separately tokenized conjunction or vocalized bi- can put the
    # noun's beginning in the following token instead.
    unmarked = ''.join(
        c for c in word if not unicodedata.combining(c) and c != 'ـ'
    )
    if not boundary and unmarked in {'ب', 'وب', 'فب'}:
        if bare == 'ِ':
            value = 10.5 * arabic_strength
        elif bare and re.fullmatch(r'\p{Script=Arabic}{1,3}', bare):
            if bare.startswith('ال') or (word.endswith('ِ') and
                    len(bare) <= 2 and bare not in {'ٱ', 'ئ'}):
                value = 9.0 * arabic_strength
            elif unmarked != 'ب':
                value = (arabic_piece('ب' + bare) or 4.0) * arabic_strength
            elif len(bare) <= 2:
                value = (5.0 if len(bare) == 1 else 2.5) * arabic_strength
            if word.endswith('َ'):
                value = 1.0 * arabic_strength
    if not boundary and word in {'لل', 'ال', 'وال', 'فال'} and bare.startswith('ب'):
        value = 0.5 * arabic_piece(bare) * arabic_strength
    if (not boundary and word in {'الب', 'البر', 'والب', 'والبر'}
            and len(bare) == 1 and (bare.isalpha() or bare == 'ِ')):
        value = 4.5 * arabic_strength

    # Latin b nearby a rounded u: including internal b, as in Cebu.
    lower = bare.lower()
    if boundary and lower.startswith('ber') and 3 <= len(lower) <= 6:
        value = 0.8
    if lower in {'bu', 'blu', 'bol'}:
        value = -0.8
    recent = previous.strip().lower()
    b_distance = len(recent) - recent.rfind('b') if 'b' in recent else 99
    if (not boundary and b_distance <= 3 and s
            and s[0].isascii() and s[0].isalpha()):
        if lower in {'u', 'ub', 'umb', 'bu', 'tu', 'us'}:
            strong = b_distance <= 2 or lower in {'ub', 'umb'}
            value = -4.0 if strong else -2.0
        elif lower == 'um' and recent == 'b':
            value = -3.0
        elif recent == 'b' and len(lower) >= 2:
            value = 0.6
    if bare and set(bare) == {'·'} and len(bare) > 1:
        value = -0.88

    match = re.search(r'[\p{L}\p{M}]+\Z', word + s)
    word = match.group()[-24:] if match else ''
    count = len(re.findall(r'\p{Script=Arabic}', s))
    arabic_count = min(15, arabic_count + count)
    return (doc, s, s[-1:] or last, persian, word, arabic_count), float(value)

"""Approximate a document-onset signal, including repeated initial tokens.

Training activations mostly vanish once the initial token changes. Estimate
pulse height from case, length, dictionary word classes, script, whitespace,
and punctuation. Sequence-boundary words get an extra boost. These broad
categories deliberately leave token-specific variation unexplained.
"""
import regex
import wordnet
from functools import lru_cache

READS = ()
CONJUNCTIONS = frozenset('''
and but or nor so yet if because although while when as than
'''.split())
SEQUENCE_BOUNDARIES = frozenset({'first', 'last', 'next', 'previous'})
FUNCTION_WORDS = frozenset('''
a an the this that these those all some any each every no
I you he she it we they me him her us them my your his its our their
in on at to of for with from by into under over between through about
without within and but or nor so yet if because although while when as than
is are am was were be been being do does did have has had will would can
could should may might must shall
'''.lower().split())


@lru_cache(maxsize=16384)
def initial_strength(text):
    word = text.strip()
    if '\ufffd' in word:
        return 0.2
    if word.startswith('<|'):
        return 3.7
    spaced = bool(text and text[0].isspace())
    value = 4.2 - 1.3 * spaced
    if not word:
        if '\n' in text:
            return 2.8
        if '\t' in text:
            return 7.3 if len(text) == 1 else 4.0
        return 3.0 if len(text) == 1 else 5.6
    if regex.search(r'\p{Script=Han}', word):
        return 1.9
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 2.2
    if word.isdecimal():
        return 6.25
    if word and set(word) == {'#'}:
        return 12.4
    if word and set(word) <= {',', '，', '、'}:
        return -0.35
    if word.startswith(('//', '/*')):
        return value + 6.2
    if word and word[0] in '([{':
        return value + 4.6
    if word.isascii() and word.isalpha():
        low = word.lower()
        if low in {'a', 'an', 'the'}:
            return 3.3
        if low in CONJUNCTIONS:
            return 0.6 if spaced and word.islower() else 4.2
        value = 4.6 - 1.7 * spaced
        length = min(len(word), 12)
        pos = wordnet.parts_of_speech(low)
        content = bool(pos) and low not in FUNCTION_WORDS
        if word.istitle():
            value += 0.45 * length + 1.1 * content
        if word.isupper():
            value += 0.7 * length
        value += 2.0 * ('verb' in pos)
        if low in SEQUENCE_BOUNDARIES:
            value += 7.6 * (2 if word.istitle() else 1)
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        first = token
    else:
        first = carry[1]
        if token != first:
            first = None
    value = 0.0
    if first is not None:
        value = initial_strength(prefix.token_strings[-1])
    return (document, first), float(value)

"""A document-start pulse, modulated by the first token's surface form.

Large training activations concentrate at document beginnings. Longer words
and words less frequent in English get larger pulses, especially unspaced
title-case words. Short function words, digits and separators get smaller pulses. Away
from document starts, retain small responses to a few article constructions.
The frequency thresholds describe corpus commonness, not a token lookup.
"""
from wordfreq import zipf_frequency

READS = ()


def initial_token(text):
    word = text.strip()
    n = len(word)
    spaced = text.startswith(' ')
    if not word:
        if '\t' in text:
            return 4.5
        if '\n' in text or '\r' in text:
            return 1.6
        return 0.2 if len(text) == 1 else 2.5
    if word.startswith('<|'):
        return 5.7 if word == '<|im_start|>' else 3.0
    if n == 1 and word.isdecimal():
        return 1.5 if int(word) < 2 else 2.8
    frequency = zipf_frequency(word, 'en')
    if n <= 2:
        if not word.isalpha():
            return 1.4 if n == 1 else 2.5
        if frequency > 6.3:
            return 1.1 if n == 1 else 2.9
        return 3.4 if spaced else 5.0
    if frequency > 7.5:
        return 1.8 if spaced else 2.2
    if frequency > 6.0:
        return 3.5 if spaced else 4.6
    if word.istitle():
        return 5.1 if spaced else 7.0
    return 5.3


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    first = prefix.position == 0 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if first:
        return None, initial_token(text)
    # Fused preposition/definite-article forms in Italian and French.
    if text in {' del', ' dell', ' della'}:
        return None, 1.0
    if text in {' delle', ' degli', ' dei'}:
        return None, 0.8
    if text == ' du':
        return None, 0.55
    if text == ' des':
        return None, 0.26
    if text == ' la':
        previous = prefix.token_strings[-2].strip().lower()
        return None, 0.9 if previous in {'de', 'a', 'à'} else 0.35
    if text in {' zum', ' zur'}:
        return None, 0.55
    if text == ' im':
        return None, 0.28
    if text in {' This', ' That', ' These', ' Those'}:
        return None, 0.22
    return None, -0.003

"""Predict local spelling responses, not sentence meaning.

The main negative pattern is a word-internal k-bearing Slavic ending,
particularly following v/в or the Slavic -ov/-ev stem ending. Cyrillic
noun endings also get a weaker response after other consonants. There
are also responses to v-prefixed numbers and a few v-continuations.
State holds only the current word and two previous tokens; documents reset it.
"""
import re

READS = ()
VOWELS = set('aeiouyаеёиоуыэюяіїє')
NOUN_K = re.compile(r'к(?:а|и|у|е|ой|ом|ах|ами|ов)?$')
ADJECTIVE_SK = re.compile(r'ск(?:ий|ая|ое|ие|ого|ому|им|их|ую|ою|ом|ими)?$')

# Columns: background, after v, extra after -ov/-ev,
#          v inside the previous token, v earlier in the word.
ENDING = {
    'Cyrillic k':    (0.0, -8.6, -2.0, -1.5, -0.8),
    'Cyrillic noun': (0.2, -3.8, -1.7, -1.9, -1.2),
    'Cyrillic sk':   (0.1, -4.0,  0.0, -1.2, -0.2),
    'Cyrillic ok':   (0.0, -2.8, -1.4, -1.1, -0.7),
    'Latin k':       (0.0, -4.0, -2.0, -0.4, -0.3),
    'Latin sk':      (0.0, -4.1, -4.8,  0.0,  0.0),
    'Latin syllable':(0.0, -4.6, -1.5, -1.3, -0.6),
    'Latin final k': (0.0, -1.0,  0.4, -0.1, -0.1),
}


def predict(s, prev, word, older):
    low, p = s.lower(), prev.lower()
    group = None
    if word and s[:1].isalpha():
        if low == 'к':
            group = 'Cyrillic k'
        elif NOUN_K.fullmatch(low):
            group = 'Cyrillic noun'
        elif ADJECTIVE_SK.fullmatch(low) or low in ('щик', 'чик'):
            group = 'Cyrillic sk'
        elif low.startswith(('ок', 'оч', 'ощ')):
            group = 'Cyrillic ok'
        elif low.isascii() and low.isalpha():
            if low == 'k':
                group = 'Latin k'
            elif low.startswith('sk'):
                group = 'Latin sk'
            elif re.fullmatch(r'k[aeiouy]|ker', low):
                group = 'Latin syllable'
            elif len(low) <= 5 and low.endswith(('k', 'ck', 'c')):
                group = 'Latin final k'
    value = 0.0
    if group:
        value, after_v, after_ov, internal, earlier = ENDING[group]
        if p.endswith(('v', 'в')):
            value += after_v
            if p.endswith(('ov', 'ev', 'ов', 'ев')):
                value += after_ov
            if len(p.strip()) > 3:
                if group in ('Cyrillic noun', 'Cyrillic ok'):
                    value += 1.4
            if group == 'Cyrillic noun' and low == 'кой':
                value -= 1.4
        elif 'v' in p or 'в' in p:
            value += internal
        elif any(c in word[-8:].lower() for c in 'vв'):
            value += earlier
        if group == 'Cyrillic noun':
            if p[-1:].isalpha() and p[-1:] not in VOWELS:
