"""A token-shape response during the document's opening run.

The first token sets the value. Exact repetitions keep it; the first change
switches it off until the next document. Formatting and digits are strongest;
word boundaries, grammatical classes, case and script calibrate ordinary text.
This deliberately omits the smaller context-dependent activations.
"""
import regex

READS = ()
PREPOSITIONS = frozenset(
    'of in for on at to from by with into over under about'.split())
AUXILIARIES = frozenset(
    'is are was were be been am do does did have has had can could will would '
    'shall should may might must'.split())
PRONOUNS = frozenset(
    'i you he she we they me him her us them my your his our their'.split())


def opening_value(text):
    s = text.strip()
    leading = bool(text and text[0].isspace())
    if text.startswith('<|'):
        return 8.4 if text == '<|endoftext|>' else 1.3
    if not s:
        if '\xa0' in text:
            return 4.4
        return 2.1 if '\n' in text else 2.8 if text == '\t' else 0.1
    if s.isdecimal():
        return 1.0 if s == '9' else 2.35
    if s in ('\\n', '\\t', '\\r'):
        return 8.9
