        return 2.3
    w = s.lower()
    if w in ('a', 'an', 'the'):
        return -0.6 if leading else 0.0 if s[0].isupper() else 0.6
    if w in ('this', 'that', 'these', 'those', 'it'):
        return -0.4
    if w in PREPOSITIONS:
        return -0.35 if leading else 0.3
    if w in ('no', 'not', 'never', 'cannot'):
        return -1.2
    if w in ('and', 'or', 'nor'):
