import re

READS = ()


def math_term(text):
    return bool(text and (text[-1].isdigit() or text[-1] in ')}]' or
                re.search(r'(?:^|[^a-zA-Z])[a-zA-Z]$', text)))


def context_strength(text):
    if text.endswith(','):
        return 2.6 + 6.1 * math_term(text[:-1].rstrip())
    if text.endswith('+'):
        return 9.4
    if text.endswith(('×', '*', '→', '·', ';')):
        return 1.5 + 5.5 * math_term(text[:-1].rstrip())
    if text.endswith('='):
        return 3.2
    if text and text[-1].isdigit():
        return 1.0 + 3.35 * bool(re.search(r'\d\.\d+$', text))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, completed, byte_tail = '', 0.0, False, b''
    else:
