        context = (tail + token[:p]).rstrip()
        long = token.count('.') > 3
        newline = '\n' in token
        value = 0.54 - 0.30 * ('…' in token) - 0.25 * long
        value += 0.14 * token.startswith(' ') - 0.25 * newline
        strength = context_strength(context)
        if s.endswith(',') and not any(ch in token[:p] for ch in "\"'[("):
            strength += 2.95
