        line = (tail + token[:p]).rsplit('\n', 1)[-1]
        if token.count('.') == 3:
            if not line.strip():
                value = 2.8 if newline else 0.75
            elif re.fullmatch(r'[ \t]*\d+[ \t]+', line):
                value = 3.4 if newline else 1.3
            elif line.rstrip().endswith(('//', '#', '/*', '*')):
                value = 1.1
        done = s.endswith(('...', '…')) and not newline
    elif '..' in token:
        number = re.search(r'\d+$', tail.rstrip())
        value = 0.9 if number and len(number.group()) > 1 else (
            0.45 if number else 0.26)
        value += 0.15 * token.startswith(' ')
    elif token.count('·') >= 2:
        value = 2.33
    elif token == ' .':
        run = re.search(r'(?:\.[ ]{0,2})+$', tail)
        n = run.group().count('.') if run else 0
        before = tail[:run.start()].rstrip() if run else tail.rstrip()
        separator = before.endswith((',', ';', '+', '×', '*', '=', '·'))
        if separator:
            before = before[:-1].rstrip()
        if n:
            i = min(n, 4) - 1
            value = (0.4, 1.8, 0.6, 0.3)[i]
            if separator and math_term(before):
                value += (3.7, 7.5, 1.8, 0.6)[i]
            elif re.search(r'(?<!\d)\d$', before):
                value += (2.3, 5.5, 1.0, 0.4)[i]
            elif before and before[-1].isdigit():
                # Long numeric identifiers often precede dotted leaders.
                value += (0.3, 0.5, 0.4, 0.2)[i]
        elif separator and math_term(before):
            value = 2.0
        done = n >= 2
    elif s in ('ld', 'cd') and tail.endswith('\\'):
        value = 4.15 if s == 'ld' else 3.5
    elif ((s == 'ots' and re.search(r'\\[lcvd]d$', tail)) or
          (s == 'dots' and tail.endswith('\\'))):
        before = re.sub(r'\\(?:[lcvd]d)?$', '', tail).rstrip()
        value = 9.9 + 2.0 * before.endswith(',')
        value -= 2.3 * tail.endswith(('vd', 'dd'))
        done = True
    elif token in (',', ' ,'):
        if re.search(r'\d+\s*,\s*[-+]?\d+\s*$', tail):
            value = 0.07 + 0.37 * bool(
                re.search(r'(?<!\d)\d\s*,\s*[-+]?\d\s*$', tail))
    elif s == 'etc':
        value = 0.44

    carry = (doc, (tail + token)[-192:], value, done, joined[-2:])
    return carry, float(value)

