"""Fires on the ellipsis of a written-out sequence, "a_1, a_2, ..., a_n" or "1 + 2 + ... + n".

The model is about to write the last term of the list, so this component is on at the
dots (and at the comma or plus sign right after them). It is strongest for LaTeX dots
(\\ldots, \\dots, \\cdots) and weak for dots in prose, code output or dot leaders.
"""
import re

READS = ()

# An ellipsis that ends the text so far.
ELLIPSIS = re.compile(r"(\.\.\.|…|[lc]?dots| \. \. \.)$")
LATEX_DOTS = re.compile(r"\\[lc]?dots$")
MATH = re.compile(r"[$\\_^{}=]|\d")
SEPARATORS = (",", "+", "\\", "=")  # what comes right before a sequence's dots


def is_sequence_dots(text):
    """True if the text ends in dots that follow a list separator."""
    m = ELLIPSIS.search(text)
    return bool(m) and text[: m.start()].rstrip().endswith(SEPARATORS)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    text = "".join(toks[-10:]).rstrip(" ,")       # the last few tokens, as text
    before = "".join(toks[-11:-1]).rstrip(" ,")   # the same without the current token
    math = bool(MATH.search("".join(toks[-20:-1])))
    if ELLIPSIS.search(text) and not ELLIPSIS.search(before) and not text.endswith("...."):
        if is_sequence_dots(text):
            if LATEX_DOTS.search(text):
                return None, 12.0
            return None, (6.0 if math else 2.0)
        return None, (1.0 if math else 0.3)
    if text.endswith(("\\ld", "\\cd")):          # "\ld" just before "ots"
        return None, (5.0 if math else 0.0)
    if is_sequence_dots(before) and cur.strip() in (",", "+"):
        return None, 9.0                           # the comma or plus right after the dots
    return None, 0.0

