"""Source-syntax cues: comments, receivers, and loop/alias keywords.

Ambiguous English words need a syntactic context. Keep the last 256 text
characters, treating escaped newlines as line breaks. Predict a negative
opening-token offset, positive responses to recognized source constructs,
and near zero elsewhere. This is a heuristic, not a source-code parser.
"""
import re

READS = ()
DECLARATIONS = {'def', 'function', 'class', 'var', 'let', 'const',
                'type', 'struct', 'interface', 'enum'}
TYPES = {'int', 'char', 'string', 'float', 'double', 'bool', 'boolean', 'void'}
MODULES = {'package', 'import', 'from', 'using'}
SQL_WORDS = {'SELECT', 'VALUES', 'THEN', 'FROM', 'BY', 'AS', 'DEFAULT'}


def response(token, recent):
    s = token.strip()
    if not recent:
        if s in DECLARATIONS:
            return -1.92
        if s in TYPES:
            return -1.58
        if s in MODULES:
            return -0.77
        if s == '#':
            return -0.23
        if s in {'//', '/*', '--'}:
            return -0.54
        if s in {'this', 'self'}:
            return -0.75
        return -0.38

    line = recent.rsplit('\n', 1)[-1]
    start = not line.strip()
    indent = start and bool(line or token[:1].isspace())
    code = bool(re.search(r'[{};=]|\w[._]\w|\b(def|return|import|function)\b',
                          recent[-180:]))
    if s in {'#', '//', '///', '--'}:
        if s == '#':
            if start:
                return 0.69 if indent else (0.74 if code else 0.40)
            return 0.19 if code else 0.12
        if start:
            return 0.61 if indent else (0.56 if code else 0.29)
        return 0.28 if code else 0.11
    if s in {'/*', '/**'}:
        return 0.06
    if s.startswith('#') and s[1:] in {
            'define', 'include', 'ifdef', 'ifndef', 'endif'}:
        return 0.25
    if s in {'this', '(this', '$this'}:
        receiver = (s != 'this' or not token.startswith(' ') or indent or
                    (code and re.search(r'(?:return|[=,(?$])\s*$', line)))
        return 0.62 if receiver else 0.035
    if s in {'self', '(self'}:
        if s == '(self' and re.search(r'\bdef\s+\w+\s*$', line):
            return 0.21
        return 0.36 if s == '(self' or code or indent else 0.0
    if s == 'in':
        loop = re.search(
            r'\b(for|foreach)\s*\(?\s*(?:(?:var|let|const|[A-Z]\w*)\s+)?'
            r'[\w.$]+(?:\s*,\s*[\w.$]+)*\s*$', line)
        statement = re.search(
            r'^\s*(?:\d+\s+)?(?:for|foreach|case)\b|[\[({]\s*for\b', line)
        if (loop and (code or statement)) or (
                statement and re.search(r'\bcase\s+.+$', line)):
            return 0.86
        return 0.02 if code else 0.0
    if s == 'as':
        alias = re.search(
            r'^\s*(?:\d+\s+)?(?:async\s+)?(?:with|except|import|from)\b|'
            r'\bforeach\s*\(', line)
        return 0.47 if alias else (0.02 if code else 0.0)
    if (s == 'else' and code and not start and
            re.search(r'\b(if|then)\b[^\n;]{0,130}$', line)):
        return 0.62
    if s == 'then':
        if code and re.search(r'\b(if|bif)\b[^\n;]{0,130}$', line):
            return 0.15
        if re.search(r'[\];]\s*$', line):
            return 0.24
    if s == 'range' and re.search(r':=\s*$', line):
        return 0.75
    if s == 'param' and re.search(r'[@<]\s*$', line):
        return 0.43
    if s == 'import' and not token.startswith(' '):
        return 0.39 if ';' in recent else -0.09
    if s in MODULES and not token.startswith(' '):
        return -0.09
    if s == 'EOF':
        return 0.85 if '<<' in line[-8:] else 0.25
    if s in SQL_WORDS:
        return 0.20
    if len(s) >= 2 and set(s) == {'·'}:
        return -0.42
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, recent)
    recent = (recent + token).replace('\\n', '\n').replace('\\t', '\t')
    return (doc, recent[-256:]), value

programs.haiku:
"""layers.1.mlp.down_proj:1456 -- a "code-context keyword" detector.

What the component does, in plain terms:
  * It is near zero on most text, and on prose it stays near zero even for words like
    "in" or "this".
  * Inside source code it switches on at a few tokens that open a statement or a
    construct:
      - a comment marker (#, ##, //, ///, --, /*), strongest at the start of a line;
      - `self` or `this` opening a line (`self.x = ...`, `this.socket = ...`);
      - the `in` of a `for ... in` loop;
      - `import` and `param`, and some SQL clause keywords (WHERE, FROM, AND, AS, IN).
  * At the first token of each document (right after <|endoftext|>, or the first token
    of a row) it dips negative: about -0.25 if that token starts with a space, about -0.5
    otherwise (fitted means: -0.25 and -0.49; the spread around them is large).

The program, `step`: at a document start it returns the dip above. Otherwise it looks up
the token being predicted, gives it a weight from the classes above (weights fitted by
least squares on training rows, then rounded), and multiplies by a "how much code is
around" gate: the share of the last 20 tokens that contain code punctuation, ramped from
10% to 30%. So the same word is weak in prose and strong in code.

What the simple version gets and misses: it reaches variance explained about 0.25 and
correlation about 0.5 on eval. The rest of the variance is spread over many tokens with
small activations (about 0.05 to 0.1), which no short list captures. A per-token mean table
with no context reaches about 0.25 on held-out training rows, about the same as this
program; combining the two was not tested.

Main program: `step`, below. It needs no state beyond the prefix it is given.
"""

READS = ()

# Characters that mark code rather than English prose.
CODE_CHARS = set("{}();=<>[]_:.#/\\*+-&|\t")
COMMENT_MARKERS = {"#", " #", "##", "//", " //", "///", " ///", "--", " --", "/*"}
SELF_WORDS = {"self", " self", "(self", "this", " this", "(this", "\tthis"}
IMPORT_WORDS = {"import", "param"}
SQL_WORDS = {" WHERE", " FROM", " AND", " AS", " IN", " DEFAULT", "SELECT", " BY", "EOF"}


def code_share(strings):
    """Fraction of the given tokens that contain code punctuation."""
    hits = sum(1 for s in strings if any(c in CODE_CHARS for c in s))
    return hits / len(strings)


def ramp(x, lo, hi):
    """0 below lo, 1 above hi, linear in between."""
    return min(1.0, max(0.0, (x - lo) / (hi - lo)))


def starts_line(strings):
    """True if the token before the current one ends a line or is only indentation."""
    if len(strings) < 2:
        return True
    before = strings[-2]
    return "\n" in before or before.strip() == ""


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    tok = strings[-1]
    # First token of a document (or of the row): the component dips negative.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.25 if tok.startswith(" ") else -0.5

    gate = ramp(code_share(strings[-20:]), 0.1, 0.3)
    if tok in COMMENT_MARKERS:
        weight = 0.6 if starts_line(strings) else 0.3
    elif tok in SELF_WORDS:
        weight = 0.8 if starts_line(strings) else 0.35
    elif tok in IMPORT_WORDS or tok in SQL_WORDS:
        weight = 0.4
    elif tok == " in":
        # `for x in ...` loops are strong; other uses of " in" are weak.
        loop = any(s.strip() == "for" for s in strings[-6:-1])
        weight = 1.0 if loop else 0.1
    else:
        weight = 0.0
    return carry, weight * gate

