"""A sparse collection of source-code boundary cues, not a full parser.

Template/PHP openings give negative pulses; namespace blocks, documentation
names and stack-trace placeholders give positive ones. Additional rules cover
document-initial markers. Most text returns zero.
A short text tail and a flag for a seen PHP opening tag are reset for each
document. This intentionally omits weak, general punctuation predictions.
"""
import re

READS = ()
HTML_TAG = re.compile(
    r'</?(?:html|head|body|div|span|h[1-6]|br|table|form|input|p)\b[^>]*>'
)
TEX_CONTEXT = re.compile(
    r'\\(?:[dt]?frac|sqrt|math\w*|text\w*|begin|end|left|right|sum|prod|lim|int)\b'
    r'|\\[\[(]'
)


def boundary_value(token, before, age, php):
    s, left = token.strip(), before.rstrip()
    # TeX's braced percentages are not source-language template openings.
    if ('%' in s or '{{' in s) and re.search(r'\\[A-Za-z]+$', left):
        return 0.0
    # PHP tags, including short echo tags embedded in markup.
    if '<?=' in s:
        return -9.8
    if s == 'php' and left.endswith('<?'):
        if age <= 1:
            return -13.37
        if before.strip() == '<?':
            return -11.0
        return -10.7 if (HTML_TAG.search(before) or '?>' in before) else -7.13
    if s.endswith('<?'):
        if age == 0:
            return -0.70
        return -5.3 if (HTML_TAG.search(before) or '?>' in before) else -2.7
    if '\n' in token and token.isspace() and left.endswith('<?php'):
        return -1.9
    if s == '_once' and left.endswith(('require', 'include')):
        return -7.7

    # Percent-delimited templates, including whitespace trimming.
    if token in ('%', '%=') and before.endswith('<'):
        return -13.0 if s == '%=' else -8.83
    if token in ('%', '%-') and before.endswith('{'):
        return -6.6 if s == '%-' else -4.70
    if s == '}{' and left.endswith('%'):
        return -2.43
    if s in ('{%', '{%-'):
        return -2.25
    if s == '_' and left.endswith('<%'):
        return -2.81
    if left.endswith('{%'):
        if s == 'set':
            return -4.41
        if s in ('for', 'include'):
            return -3.2
    if '{{' in s:
        if s.startswith('="'):
            return -5.13
        if s.startswith('>') or left.endswith('%}'):
            return -4.55
        if s.startswith(('"', "'")) or left.endswith(('"', "'", '`')):
            return -2.43
        if '{%' in before or 'template' in before.lower():
            return -2.55
        return 0.0 if TEX_CONTEXT.search(before) else -1.6

    # Namespace block openings, rather than ordinary opening braces.
    if s == '{' and re.search(r'\bnamespace(?:\s+[\w.:]+)?\s*$', left):
        return 3.13

    # Names in angle brackets: XML documentation and stack traces.
    name = s.lstrip('<').lower()
    if s.startswith('<') or left.endswith(('<', '</')):
        if name in ('anonymous', 'computed'):
            return 2.69
        if name == 'param':
            return 1.90 if left.endswith('</') else 2.25
        if name in ('summary', 'returns', 'see'):
            return {'summary': 0.54, 'returns': 1.02, 'see': 3.85}[name]
    # Line-initial PHP statements; recognize escaped source-code newlines too.
    if s in ('echo', 'require', 'include') or (s == 'cho' and left.endswith('e')):
        context = before.replace('\\n', '\n').replace('\\t', '\t')
        if s == 'cho':
            context = context[:-1]
        if re.search(r'(?:^|\n)\s*$', context):
            php_variables = re.search(r'\$\w+\s*=(?!=)', before) and ';' in before
            if php or php_variables:
                return -2.0
            if '\\n' in before[-12:] or '\\t' in before[-12:]:
                return -1.6 if s in ('echo', 'cho') else 0.0
            return -0.25 if s in ('echo', 'cho') else 0.0
    if s == 'function' and left.endswith('<'):
        return -1.69
    if s == ':' and left == 'Title':
        return 8.20
    if age == 0:
        if s == '#':
            return -0.50
        if s == '<|endoftext|>':
            return 3.29
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, age, php = '', 0, False
    else:
        _, before, age, php = carry
    token = prefix.token_strings[-1]
    value = boundary_value(token, before, age, php)
    php = php or (token.strip() == 'php' and before.rstrip().endswith('<?'))
    return (doc, (before + token)[-400:], age + 1, php), value

programs.haiku:
"""Negative activation inside Python code, strongest on assignment statements.

What it does: this component is quiet in ordinary prose and goes negative in code. The
biggest negative values come on the '=' of an assignment to a bare name or attribute
(`x = ...`, `self.y = ...`, `data = ...`) that starts a line; other '=' tokens are weak.
Keywords, self, library names, and code idioms such as `(f`, `.py`, `):`, `":` are
moderately negative too. Every value is scaled by how code-like the last 32 tokens of the
document are, so the same token is near zero in prose and negative in code.

Predicted activation = -(group weight) * (share of code-like tokens among the last 32).
"""

READS = ()

import re

PY_KEYWORDS = {'def', 'class', 'import', 'from', 'return', 'if', 'elif', 'else', 'try', 'except',
               'with', 'as', 'for', 'in', 'while', 'raise', 'yield', 'lambda', 'pass', 'assert',
               'print', 'None', 'True', 'False'}
SELF_LIKE = {'self', 'kwargs', 'len', 'str', 'int', 'range'}
LIBS = {'np', 'pd', 'os', 'sys', '.py'}
IDIOMS = {'(f', '(**', '):', ':\n', '):\\', '":', "['", 'kwargs'}
CODE_TOKENS = {'=', '(', '):', ':\n', '):\\', '._', '__', '":', "['", '(f', '.py', '(**'}
CODE_LIKE = re.compile(r'[(){}\[\]=:;_#.]|^\s{2,}|\n\s{2,}')
ASSIGN_LHS = re.compile(r'^\s*(self\.)?[A-Za-z_][\w.\[\]\'"]*\s*$')
WINDOW = 32


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        flags, line = (), ''
    else:
        flags, line = carry[1], carry[2]
    word = tok.strip()
    is_code = (word in PY_KEYWORDS or word in SELF_LIKE or word in CODE_TOKENS or tok in CODE_TOKENS
               or bool(CODE_LIKE.search(tok)))
    flags = (flags + (1.0 if is_code else 0.0,))[-WINDOW:]
    ctx = sum(flags) / len(flags)
    if word == '=':
        w = -2.2 if ASSIGN_LHS.match(line) else -0.5
    elif word in PY_KEYWORDS:
        w = -0.5
    elif word in SELF_LIKE:
        w = -1.1
    elif word in LIBS:
        w = -2.7
    elif tok in IDIOMS or word in IDIOMS:
        w = -1.8
    elif tok.startswith('.') or '__' in tok:
        w = -0.25
    else:
        w = 0.0
    line = '' if '\n' in tok else (line + tok)[-200:]
    return (doc, flags, line), w * ctx

programs.sol:
"""A recognizer for degree and quantity constructions, not ordinary articles.

Large positives mark 'such/quite/what a', 'a bit of a', and 'too big a'.
Other rules cover number multipliers and Chinese numeral compounds.
Manner/direction phrases ('which way') have negative signs.
Title punctuation at a document start and middle-dot padding are separate
formatting cases. Everything else is zero. These rules approximate the large,
sparse responses, leaving small background and miscellaneous lexical effects
unmodeled. State is only a short text tail, reset between documents.
"""
import re
import inflect
import wordnet

READS = ()
CARDINALS = {inflect.engine().number_to_words(n): n for n in range(1, 20)}
FUNCTION_WORDS = frozenset('''
    a an the all any both each either every few many more most much neither
    no none other several some such that these this those in on through off
    out over under just even i you he she it we they me us him her them
    my our your his its their who whom whose
'''.split()) | CARDINALS.keys()
ARTICLE_STARTERS = {'such': 7.2, 'what': 8.3, 'quite': 8.3,
                    'half': 5.6, 'many': 2.5, 'rather': 2.5}
OF_PHRASES = {'bit': 7.4, 'much': 6.5, 'more': 5.0, 'enough': 6.0,
              'kind': 5.4, 'type': 3.5, 'something': 7.2, 'somewhat': 7.2,
              'quarter': 3.0, 'quarters': 4.5, 'third': 1.5, 'fraction': 1.6}
DEGREES = {'as': 12.0, 'so': 13.5, 'too': 17.0, 'how': 9.5}

CANDIDATES = frozenset({
    'a', 'an', '-a', 'way', 'ways', 'hundred', 'hundreds', 'thousand',
    'thousands', 'dozen', 'dozens', 'decade', 'decades', 'decimal',
    'decimals', ':', '··'})


def adjective(word):
    return word.isalpha() and word not in FUNCTION_WORDS and (
        'adjective' in wordnet.parts_of_speech(word))


def predict(token, tail):
    # Punctuation terminates a phrase; whitespace does not.
    match = re.search(r'([A-Za-z]+(?:[\s-]+[A-Za-z]+)*)\s*$', tail)
    words = re.findall('[A-Za-z]+', match[0].lower()) if match else []
    last = words[-1] if words else ''
    before = words[-2] if len(words) > 1 else ''
    third = words[-3] if len(words) > 2 else ''
    if token in (' a', ' an', 'a', 'an', '-a') and (
            token[0] in ' -' or tail[-1:].isspace()):
        if last in ARTICLE_STARTERS:
            return ARTICLE_STARTERS[last]
        if last == 'of':
            if before in OF_PHRASES:
                return OF_PHRASES[before]
            if third in ('so', 'too', 'how', 'that'):
                return 12.0 if adjective(before) else 0.0
        degree = before
        if before.endswith('ly') and third in DEGREES:
            degree = third
        if degree in DEGREES and adjective(last):
            # 'Used as ...' describes a role, not an extent/comparison.
            role = third not in ('is', 'was', 'be', 'are') and (
                'verb' in wordnet.parts_of_speech(third))
            if not (degree == 'as' and role):
                return DEGREES[degree] * (0.8 if degree != before else 1.0)
        if last == 'even':
            return 0.6
    current = token.strip().lower()
    if current == 'way':
        if last in ('which', 'whichever'):
            return -5.8
        if last == 'either':
            return -2.0
        if last in ('this', 'that', 'other', 'every', 'one', 'two', 'any'):
            return -0.1 if before == 'in' else -1.4
    if current == 'ways':
        if last == 'both':
            return -2.9
        if last in CARDINALS or last in ('many', 'few', 'several', 'different'):
            return -0.9
        if last == 'of' and before == 'number':
            return -1.1
    if current in ('hundred', 'hundreds', 'thousand', 'thousands',
                    'dozen', 'dozens', 'decade', 'decades', 'decimal', 'decimals'):
        number = re.search(r'(\d+|[A-Za-z]+)\s*$', tail)
        number = number[1].lower() if number else ''
        count = int(number) if number.isdigit() else CARDINALS.get(number, 0)
        if count >= 2 or number in ('several', 'few', 'many'):
            if current in ('hundred', 'hundreds'):
                return 2.3 if 2 <= count <= 9 else 1.4
            return 0.9
    if token and tail and token[0] in '十百千' and (
            tail[-1] in '一二三四五六七八九两兩幾几数'):
        return 5.4 if token[0] == '十' else 3.5
    if token == ':' and (tail == 'Title' or tail.endswith('<|endoftext|>Title')):
        return 5.9
    if token == '··':
        return -1.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    # Only these tokens can match; avoid parsing ordinary text at every step.
    value = predict(token, tail) if token.strip().lower() in CANDIDATES or (
        token and token[0] in '十百千') else 0.0
    return (doc, (tail + token)[-120:]), value

"""Approximate detector of Indonesian/Malay prefix fragments.

Completed function words supply language context. Short me-/pe-/di-
beginnings then receive large negative pulses; longer pieces and capitals
receive smaller ones. A few fragments get weak pulses even without that
context. Local spelling rules also cover Persian mi-, Arabic verb beginnings,
Hungarian meg-, and a few Cyrillic/diacritic combinations. Other tokens are
left at zero. State resets at document boundaries and end-of-text markers.
"""

READS = ()
ENGLISH = set('the of and to is that with for was are be by this which his '
              'from not have has but you your'.split())
# Short beginnings of active meN-, nominal peN-, and passive di- words.
PREFIXES = {
    'menc': -13.0, 'meng': -10.5, 'meny': -10.8, 'mend': -8.5,
    'mem': -10.5, 'men': -10.0, 'mel': -8.0, 'mer': -8.5, 'me': -4.0,
    'penc': -7.5, 'peng': -4.8, 'peny': -7.0, 'pend': -4.0,
    'pem': -4.5, 'pen': -5.2,
    'dip': -9.0, 'dit': -10.0, 'did': -8.0, 'dib': -8.0, 'dik': -7.5,
    'dig': -6.0, 'dim': -5.8, 'dil': -5.0, 'dir': -5.5, 'dis': -5.5,
    'di': -6.5,
}


# Indonesian/Malay closed-class words; avoid shared words such as Italian di.
INDONESIAN = set('yang untuk dengan tidak itu dari dalam sebagai akan karena '
                 'saya kita sudah telah juga adalah oleh atau bahwa dapat '
                 'tersebut kepada mereka serta lebih bukan'.split())


def language_word(word):
    if word in {'Yang', 'Kita', 'Saya'}:
        return 0.0  # These capitalized forms are also common personal names.
    lower = word.lower()
    if lower in ENGLISH:
        return -0.7
    return 1.5 if lower in INDONESIAN else 0.0


def onset(fragment):
    """Short subword beginnings, with weaker pulses for longer pieces."""
    if len(fragment) > 6:
        return 0.0
    for prefix, strength in PREFIXES.items():
        if fragment.startswith(prefix):
            return strength * (0.72 ** (len(fragment) - len(prefix)))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, language, persian = '', 0.0, False
    else:
        _, word, language, persian = carry
    s = prefix.token_strings[-1]
    old = word
    beginning = s[:1].isspace() or not old
    t = s.strip().lower()
    for ch in s:
        if ch.isalpha():
            word = (word + ch)[-40:]
        elif word:
            language = max(0.0, language * 0.97 + language_word(word))
            word = ''
    language = min(language, 6.0)
    gate = min(1.0, language / 0.7)
    # Usually the current token itself is the prefix. Occasionally a single
    # consonant was split off into the previous token.
    value = 0.0
    if beginning:
        value = gate * onset(t)
    elif old.lower() in {'m', 'p', 'd'}:
        value = gate * 0.85 * onset(old.lower() + t)
    if beginning:
        if t in {'m', 'd'}:
            value = -gate * (1.8 if t == 'm' else 4.0)
        elif t in {'ber', 'ter', 'per'}:
            value = -gate * 0.55
        elif t in {'saya', 'anda', 'kami', 'kita'}:
            value = -gate * (2.2 if t == 'kita' else 0.9)
        elif t in {'ي', 'ت', 'يت', 'وي', 'تح'}:
            value = (0.1 if persian else -1.15)
        elif t == 'meg':
            value = -0.7
    if beginning and s.strip()[:1].isupper():
        value *= 0.25 if len(t) == 1 else 0.65
    if beginning and not gate:
        fragments = {'mem', 'mel', 'menc', 'meng', 'meny', 'mend'}
        if t in fragments or s.strip()[:1].isupper():
            value = 0.08 * onset(t)
    if old in {'م', 'نم'} and (s[:1] in {'ی', 'ى'} or
                              (persian and s.startswith('ي'))):
        value = -7.8 if s == 'ی' else -5.6
        if old == 'نم':
            value *= 0.6
    if old.lower() in {'m', 'м', 'д'} and s[:1] in {'ě', 'ē', 'і'}:
        value = -1.1
    if old.lower() == 'д' and s.startswith('ж'):
        value = -3.0
    if old.lower() in {'me', 'mé'} and s.startswith('g'):
        value = -3.6
    persian = persian or any(ch in s for ch in 'یگکپچ')
    if '<|endoftext|>' in s:
        word, language, persian = '', 0.0, False
    return (doc, word, language, persian), float(value)

"""Indefinite noun-phrase openings, especially English a/an.

Whitespace and sentence boundaries distinguish articles from word fragments
and capital-letter labels. Predeterminers (such/what) suppress the response;
ordinary grammatical contexts adjust its strength. A small vocabulary covers
other indefinite expressions and articles in several languages.
This is a lexical/grammatical approximation, not a parser.
"""

import re

READS = ()

# Inflected German indefinite articles, and Romance, Dutch, Hungarian,
# Swedish and Vietnamese equivalents of English a/an.
ARTICLES = {
    'ein': 1.2, 'eine': 1.1, 'einer': 0.85,
    'einem': 0.85, 'einen': 0.85, 'eines': 0.3,
    'un': 0.5, 'une': 0.7, 'una': 0.7,
    'um': 0.4, 'uma': 0.75,
    'een': 1.75, 'egy': 1.9, 'ett': 2.5, 'một': 0.75,
}
COPULAS = {'be', 'is', 'am', 'are', 'was', 'were', 'been', 'being'}
POSSESSION = {'has', 'have', 'had'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    first = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else prefix.token_strings[-2]
    fragment = (token[:1].isalnum() and
                previous[-1:].isalnum())

    if lower in {'a', 'an'}:
        if first:
            return None, 0.1 if word.islower() else -0.05
        if fragment:
            return None, 0.08 if word.islower() else -0.1
        if not word.islower():
            sentence_start = ('\n' in previous or
                              previous.rstrip().endswith(('.', '!', '?')))
            if sentence_start:
                return None, 1.0
            if previous.rstrip().endswith((':', '-', '—', '"', '“')):
                return None, 0.6
            return None, 0.0
        match = re.search(r'(\w+)\s*$', previous)
        prev_word = match[1].lower() if match else ''
        if prev_word in {'such', 'what'}:
            value = -0.45
        elif prev_word in {'as', 'was', 'were'}:
            value = 0.6
        elif prev_word in COPULAS | POSSESSION | {'in', 'at', 'of', 'on', 'into'}:
            value = 0.85
        elif prev_word in {'to', 'by', 'and', 'or'}:
            value = 1.25
        elif previous.rstrip().endswith(('=', '+', '-', '*', '/', '$', '_', ':')):
            value = 0.1
        else:
            value = 1.05
        return None, value

    # Chinese quantifiers do not require spaces between words.
    if word.endswith(('一个', '一些')):
        return None, 0.5
    if fragment:
        return None, 0.0
    if previous.strip().lower() == 'a':
        # Small-quantity idioms, versus the quantity noun in a lot.
        if lower in {'few', 'little'}:
            return None, 0.5
        if lower == 'lot':
            return None, -0.33
    if lower in ARTICLES:
        # Unspaced forms are often word fragments rather than articles.
        value = ARTICLES[lower] if token[:1].isspace() else 0.2
        if word.isupper():
            value = 0.0
        elif not word.islower():
            value *= 0.7
        return None, value
    if lower == 'another':
        return None, 0.74
    if lower == 'some':
        return None, 0.6 if word.islower() else 0.15
    if lower == 'something':
        return None, 0.65
    if lower in {'someone', 'somebody'}:
        return None, 0.32
    if lower in {'anything', 'anyone', 'anybody'}:
        return None, 0.24
    return None, -0.002

"""A row/document-initial signal with coarse lexical and character-shape tuning.

Recognized greetings, time words and code preludes are strongly positive;
articles, copulas and the question openers "What" and "Which" are negative.
Protocol markers have their own signs. Otherwise case, length and script
supply an average, not a word-by-word lookup. After a different token has
appeared, the large initial signal stops. An initial run of identical tokens
keeps it alive. Most later activations are approximated by a near-zero value.
"""
import regex

READS = ()


def first_value(token):
    word = token.strip().lower()
    if token == '<|endoftext|>':
        return -16.07
    if token == '<|im_start|>':
        return 4.55
    if token.startswith(('<|', '</tool_', '<think', '</think')):
        return 3.9
    if not word:
        return -0.2
    if word == 'welcome':
        return 13.6
    if word in {'hello', 'hi', 'hey', 'greetings'}:
        return 21.0
    if word in {'today', 'yesterday', 'tomorrow', 'tonight',
                'recently', 'currently'}:
        return 9.5
    if word in {'what', 'which'} and token[:1].isupper():
        return -7.3
    if word in {'import', 'package', 'using', 'namespace'}:
        return 6.9
    if word in {r'\n', r'\t', r'\r'}:
        return 10.0
    if word.startswith(('/*', '#!/', '#include')):
        return 4.0
    if word in {'a', 'an', 'the'}:
        return -1.7
    if word in {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}:
        return -1.1
    # Purpose, direction, possession, location and accompaniment words.
    if word == 'for':
        return 8.0
    if word == 'to':
        return 2.5
    if word == 'of':
        return 0.25
    if word == 'in' or word == 'or':
        return -1.1
    if word == 'with':
        return 5.5
    if word.isdigit():
        return -1.0 if word in {'0', '1', '2'} else 0.4
    if word and set(word) <= set('·•'):
        return 7.0
    if not any(c.isalpha() for c in word):
        if word and set(word) <= set('.,?!#'):
            return -0.8 if len(word) == 1 else 1.0
        return 0.3
    # Coarse shape-dependent baseline for otherwise unclassified tokens.
    value = 2.69 + 1.04 * token.strip().istitle()
    value += 0.096 * min(len(token.strip()), 20)
    value -= 2.06 * token.strip().isascii()
    if regex.search(r'\p{Script=Han}', token):
        value -= 1.03
    if regex.search(r'\p{Script=Greek}', token):
        value -= 2.26
    if regex.search(r'\p{Script=Hangul}', token):
        value += 1.64
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = first_value(token)
        return (doc, token_id, value, True), value
    _, first, value, repeating = carry
    repeating = repeating and token_id == first
    return (doc, first, value, repeating), value if repeating else -0.002

programs.haiku:
"""Document-opening detector (layer 1 MLP, component 1463).

Fires almost only on the first token of a document (after <|endoftext|>, or the first
token of a row). Its value there depends on what that opening word is: greetings and
exclamations ("Hello", "Hi", "Wow", "Congratulations", "Please") push it strongly
positive; question and conditional openers ("What", "Which", "Who", "Would", "If", "When")
push it negative; articles and prepositions ("The", "A", "In") sit near zero; code
openers ("import", "using") are positive. Other opening words get a small positive value.
The value is held while the document is still one token repeated, and is 0 elsewhere.
"""

READS = ()

SPECIAL = {"<|endoftext|>": -16.0, "<|im_start|>": 4.5}
GREETINGS_AND_EXCLAMATIONS = {
    "hello", "hi", "hey", "hallo", "hola", "greetings", "dear", "welcome", "congratulations",
    "congrats", "sure", "okay", "ok", "alright", "thanks", "thank", "please", "wow", "oops",
    "yay", "oh", "ah", "uh", "hmm", "lol", "oi", "bonjour", "hei", "ciao", "certainly",
    "great", "happy", "well", "yes", "here", "now", "let", "our", "nice", "good",
    "亲爱的", "嘿", "你好", "大家好", "各位", "欢迎",
}
TIME_WORDS = {
    "today", "tonight", "yesterday", "recently", "currently", "nearly", "almost", "monday",
    "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
}
CODE_OPENERS = {"import", "package", "using", "#include", "/*", "*"}
QUESTION_WORDS = {"what", "which", "who", "whom", "whose", "would", "if", "when", "but", "just",
                  "could", "does", "where"}
ARTICLES_PREPOSITIONS = {"the", "a", "an", "in", "at", "by", "as", "is", "or", "¿"}

GREETING_VALUE = 9.0
TIME_VALUE = 7.0
CODE_VALUE = 5.0
QUESTION_VALUE = -6.0
ARTICLE_VALUE = -1.0
PUNCT_VALUE = -0.5
OTHER_VALUE = 2.0


def opening_value(token: str) -> float:
    """The component's value at the first token of a document, from its text."""
    if token in SPECIAL:
        return SPECIAL[token]
    word = token.strip().lower()
    if word in GREETINGS_AND_EXCLAMATIONS:
        return GREETING_VALUE
    if word in TIME_WORDS:
        return TIME_VALUE
    if word in CODE_OPENERS:
        return CODE_VALUE
    if word in QUESTION_WORDS:
        return QUESTION_VALUE
    if word in ARTICLES_PREPOSITIONS:
        return ARTICLE_VALUE
    if not any(c.isalnum() for c in word):
        return PUNCT_VALUE
    return OTHER_VALUE


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = (
        len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if new_document:
        first, repeated, value = prefix.token_ids[-1], True, opening_value(token)
    else:
        first, repeated, value = carry
        repeated = repeated and prefix.token_ids[-1] == first
    carry = (first, repeated, value)
    return carry, (value if repeated else 0.0)

programs.sol:
"""Approximate auxiliary 'be' constructions and a few document-opening effects.

The largest linguistic response is to 'being' after a finite form of 'be'.
The base form 'be' is weaker, especially after future or hypothetical modals.
Separate rules cover the digit 2 in numbers and initial '12' or 'Title:'.
Other tokens are zero, apart from a small document-initial offset. This is
a coarse approximation: most token-specific variation is deliberately omitted.
"""
READS = ()

FINITE_BE = {'is', 'are', 'was', 'were', 'am'}
MODALS = {
    'can': 0.19, 'cannot': 0.16, 'could': 0.035,
    'shall': 0.04, 'should': 0.01,
    'will': -0.035, 'would': -0.055,
    'may': -0.07, 'must': -0.025, 'might': -0.09,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, recent = 0, []
    else:
        _, n, recent = carry
    token = prefix.token_strings[-1]
