            return -0.63 if len(word) <= 1 else 0.06
        return 0.51 if frequency <= 5.3 else -0.58
    if frequency <= 6.2:
        return 1.28 if word[0].isupper() else 0.27
    return -0.14 if frequency <= 6.8 else -0.72


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = opening_value(prefix.token_strings[-1])
        return (document, token, value), value
    if token == carry[1]:
        return carry, carry[2]
    return (document, None, 0.0016), 0.0016
